function getVipCleanServiceCodesForGame(game) {
  const key = VIP_GAME_ALIASES[normalizeText(game)] || game;
  return Array.isArray(VIP_GAME_SERVICE_CODES[key]) ? VIP_GAME_SERVICE_CODES[key] : [];
}

function isKnownVipCleanServiceCode(code) {
  const needle = String(code || "").trim();
  if (!needle) return false;
  return Object.values(VIP_GAME_SERVICE_CODES).some(list => list.includes(needle));
}


