// =========================================================
// VIP LIVE CATALOG / HARGA / OVERRIDE DEV
// Semua kode + nama nominal + harga dasar diambil dari VIP Reseller.
// Harga jual website boleh diubah Dev tanpa mengubah kode VIP.
// =========================================================
const VIP_CATALOG_FILE = path.join(DATA_DIR, "vip-catalog.json");
const VIP_CATALOG_META_FILE = path.join(DATA_DIR, "vip-catalog-meta.json");
if (!fs.existsSync(VIP_CATALOG_FILE)) fs.writeFileSync(VIP_CATALOG_FILE, "{}");
if (!fs.existsSync(VIP_CATALOG_META_FILE)) fs.writeFileSync(VIP_CATALOG_META_FILE, "{}");

let vipCatalog = {};
let vipCatalogMeta = {};
try { vipCatalog = JSON.parse(fs.readFileSync(VIP_CATALOG_FILE, "utf8") || "{}"); } catch { vipCatalog = {}; }
try { vipCatalogMeta = JSON.parse(fs.readFileSync(VIP_CATALOG_META_FILE, "utf8") || "{}"); } catch { vipCatalogMeta = {}; }

function saveVipCatalog() {
  fs.writeFileSync(VIP_CATALOG_FILE, JSON.stringify(vipCatalog, null, 2));
}
function saveVipCatalogMeta() {
  fs.writeFileSync(VIP_CATALOG_META_FILE, JSON.stringify(vipCatalogMeta, null, 2));
}
function vipPrice(item) {
  const level = String(process.env.VIP_PRICE_LEVEL || "basic").toLowerCase();
  const prices = item?.price && typeof item.price === "object" ? item.price : {};
  return Number(prices[level] ?? prices.basic ?? prices.member ?? item?.price ?? 0);
}
function normalizeVipCatalogItem(item) {
  const code = String(item?.code || "").trim();
  if (!code) return null;
  const basePrice = vipPrice(item);
  const override = vipCatalog[code]?.sellingPrice;
  return {
    code,
    game: String(item?.game || "").trim(),
    name: String(item?.name || item?.description || code).trim(),
    description: String(item?.description || "").trim(),
    server: item?.server ?? "",
    status: String(item?.status || "available").toLowerCase(),
    vipPrice: basePrice,
    price: Number.isFinite(Number(override)) && Number(override) > 0 ? Number(override) : basePrice,
    sellingPrice: Number.isFinite(Number(override)) && Number(override) > 0 ? Number(override) : basePrice,
    priceOverridden: Number.isFinite(Number(override)) && Number(override) > 0,
    enabled: vipCatalog[code]?.enabled !== false,
    displayName: vipCatalog[code]?.displayName || "",
    sortOrder: Number(vipCatalog[code]?.sortOrder) || 0,
    note: vipCatalog[code]?.note || "",
    updatedAt: vipCatalog[code]?.updatedAt || null,
    vipUpdatedAt: vipCatalog[code]?.vipUpdatedAt || null
  };
}

async function fetchVipServicesLive() {
  const result = await vipRequest({ type: "services", filter_status: "available" });
  if (result?.result === false) throw new Error(result?.message || "VIP Reseller menolak permintaan katalog");
  const list = Array.isArray(result?.data) ? result.data : [];
  return list.filter(x => String(x?.status || "available").toLowerCase() === "available");
}

async function refreshVipCatalog(reason = "timer") {
  if (!isConfigured(VIP_API_ID) || !isConfigured(VIP_API_KEY)) return { changed: false, count: Object.keys(vipCatalog).length };
  try {
    const list = await fetchVipServicesLive();
    const now = new Date().toISOString();
    const next = {};
    let changed = false;
    const changes = [];

    for (const raw of list) {
      const code = String(raw?.code || "").trim();
      if (!code) continue;
      const vip = vipPrice(raw);
      if (!(vip > 0)) continue;
      const old = vipCatalog[code];
      const oldVip = Number(old?.vipPrice || 0);
      const oldName = String(old?.name || "");
      const oldGame = String(old?.game || "");
      const oldStatus = String(old?.status || "");
      // Hanya harga jual yang benar-benar diatur Dev yang dipertahankan; selain itu ikut harga provider.
      const wasOverridden = old && (old.priceOverridden === true || (Number(old.sellingPrice) > 0 && Number(old.sellingPrice) !== Number(old.vipPrice)));
      const override = wasOverridden && Number(old.sellingPrice) > 0 ? Number(old.sellingPrice) : null;
      const item = {
        code,
        game: String(raw?.game || "").trim(),
        name: String(raw?.name || raw?.description || code).trim(),
        description: String(raw?.description || "").trim(),
        server: raw?.server ?? "",
        status: String(raw?.status || "available").toLowerCase(),
        vipPrice: vip,
        sellingPrice: override || vip,
        priceOverridden: Boolean(override),
        enabled: old?.enabled !== false,
        displayName: old?.displayName || "",
        sortOrder: Number(old?.sortOrder) || 0,
        note: old?.note || "",
        updatedAt: old?.updatedAt || now,
        vipUpdatedAt: now
      };
      next[code] = item;

      if (!old || oldVip !== vip || oldName !== item.name || oldGame !== item.game || oldStatus !== item.status) {
        changed = true;
        changes.push({
          code,
          game: item.game,
          name: item.name,
          oldVipPrice: oldVip || null,
          vipPrice: vip,
          sellingPrice: item.sellingPrice,
          type: !old ? "NEW" : oldVip !== vip ? "PRICE_CHANGED" : "UPDATED"
        });
      }
    }

    // Produk yang sudah tidak tersedia jangan lagi ditampilkan di katalog aktif.
    const oldCodes = Object.keys(vipCatalog);
    for (const code of oldCodes) {
      if (!next[code]) {
        changed = true;
        changes.push({
          code,
          game: vipCatalog[code]?.game || "",
          name: vipCatalog[code]?.name || code,
          oldVipPrice: vipCatalog[code]?.vipPrice || null,
          vipPrice: null,
          sellingPrice: null,
          type: "REMOVED"
        });
      }
    }

    // Catat produk yang hilang dari katalog VIP supaya checkout bisa diblokir
    // dan halaman bisa menampilkannya sebagai nonaktif (bukan lenyap begitu saja).
    const removedCodes = { ...(vipCatalogMeta.removedCodes || {}) };
    for (const c of Object.keys(next)) delete removedCodes[c];
    for (const c of oldCodes) {
      if (!next[c]) {
        removedCodes[c] = {
          at: now,
          game: vipCatalog[c]?.game || "",
          name: vipCatalog[c]?.name || c,
          price: Number(vipCatalog[c]?.sellingPrice || vipCatalog[c]?.vipPrice || 0)
        };
      }
    }

    vipCatalog = next;
    saveVipCatalog();

    vipCatalogMeta = {
      success: true,
      removedCodes,
      gameSettings: vipCatalogMeta.gameSettings || {},
      lastSyncAt: now,
      reason,
      changed,
      changeCount: changes.length,
      changes: changes.slice(0, 500),
      total: Object.keys(next).length,
      priceLevel: String(process.env.VIP_PRICE_LEVEL || "basic").toLowerCase()
    };
    saveVipCatalogMeta();

    if (changed) {
      console.log(`VIP CATALOG BERUBAH: ${changes.length} perubahan, total ${Object.keys(next).length}`);
    } else {
      console.log(`VIP CATALOG SYNC OK: ${Object.keys(next).length} produk`);
    }

    return { changed, count: Object.keys(next).length, changes };
  } catch (error) {
    console.error("VIP CATALOG SYNC:", error.response?.data || error.message);
    vipCatalogMeta = {
      ...vipCatalogMeta,
      success: false,
      lastErrorAt: new Date().toISOString(),
      error: error.message
    };
    saveVipCatalogMeta();
    return { changed: false, count: Object.keys(vipCatalog).length, error: error.message };
  }
}

