if (!fs.existsSync(MELO_CATALOG_META_FILE)) fs.writeFileSync(MELO_CATALOG_META_FILE, "{}");

let meloCatalog = {};
let meloCatalogMeta = {};
try { meloCatalog = JSON.parse(fs.readFileSync(MELO_CATALOG_FILE, "utf8") || "{}"); } catch { meloCatalog = {}; }
try { meloCatalogMeta = JSON.parse(fs.readFileSync(MELO_CATALOG_META_FILE, "utf8") || "{}"); } catch { meloCatalogMeta = {}; }

function saveMeloCatalog() {
  fs.writeFileSync(MELO_CATALOG_FILE, JSON.stringify(meloCatalog, null, 2));
}
function saveMeloCatalogMeta() {
  fs.writeFileSync(MELO_CATALOG_META_FILE, JSON.stringify(meloCatalogMeta, null, 2));
}
function normalizeMeloCatalogItem(item) {
  const code = String(item?.code || "").trim();
  if (!code) return null;
  const basePrice = Number(item?.modalPrice ?? 0);
  const override = meloCatalog[code]?.sellingPrice;
  return {
    code,
    game: String(item?.game || "").trim(),
    name: String(item?.name || code).trim(),
    status: String(item?.status || "active").toLowerCase(),
    inquiryFields: item?.inquiryFields || null,
    meloPrice: basePrice,
    price: Number.isFinite(Number(override)) && Number(override) > 0 ? Number(override) : basePrice,
    sellingPrice: Number.isFinite(Number(override)) && Number(override) > 0 ? Number(override) : basePrice,
    priceOverridden: Number.isFinite(Number(override)) && Number(override) > 0,
    enabled: meloCatalog[code]?.enabled !== false,
    displayName: meloCatalog[code]?.displayName || "",
    sortOrder: Number(meloCatalog[code]?.sortOrder) || 0,
    note: meloCatalog[code]?.note || "",
    updatedAt: meloCatalog[code]?.updatedAt || null,
    meloUpdatedAt: meloCatalog[code]?.meloUpdatedAt || null
  };
}

async function fetchMeloPricelistLive() {
  const result = await meloRequest("GET", "/api/v1/h2h/pricelists");
  if (result?.success === false) throw new Error(result?.message || "MeloStore menolak permintaan pricelist");
  const list = Array.isArray(result?.data) ? result.data : [];
  // GAME ONLY dulu (belum aplikasi/PPOB), sesuai instruksi kamu.
  return list.filter(x =>
    String(x?.category_name || "").toLowerCase() === "game" &&
    String(x?.status || x?.h2h_status || "active").toLowerCase() === "active"
  );
}

async function refreshMeloCatalog(reason = "timer") {
  if (!isConfigured(MELO_API_KEY) || !isConfigured(MELO_SECRET_KEY)) return { changed: false, count: Object.keys(meloCatalog).length };
  try {
    const list = await fetchMeloPricelistLive();
    const now = new Date().toISOString();
    const next = {};
    let changed = false;
    const changes = [];

    for (const raw of list) {
      const code = String(raw?.sku_code || "").trim();
      if (!code) continue;
      const modalPrice = Number(raw?.price || 0);
      if (!(modalPrice > 0)) continue;
      const old = meloCatalog[code];
      const oldPrice = Number(old?.meloPrice || 0);
      const oldName = String(old?.name || "");
      const oldGame = String(old?.game || "");
      const wasOverridden = old && (old.priceOverridden === true || (Number(old.sellingPrice) > 0 && Number(old.sellingPrice) !== Number(old.meloPrice)));
      const override = wasOverridden && Number(old.sellingPrice) > 0 ? Number(old.sellingPrice) : null;
      const item = {
        code,
        game: String(raw?.brand_name || raw?.type_name || "").trim(),
        name: String(raw?.name || code).trim(),
        status: "active",
        inquiryFields: raw?.inquiry_fields || null,
        modalPrice,
        meloPrice: modalPrice,
        sellingPrice: override || modalPrice,
        priceOverridden: Boolean(override),
        enabled: old?.enabled !== false,
        displayName: old?.displayName || "",
        sortOrder: Number(old?.sortOrder) || 0,
        note: old?.note || "",
        updatedAt: old?.updatedAt || now,
        meloUpdatedAt: now
      };
      next[code] = item;

      if (!old || oldPrice !== modalPrice || oldName !== item.name || oldGame !== item.game) {
        changed = true;
        changes.push({
          code,
          game: item.game,
          name: item.name,
          oldPrice: oldPrice || null,
          newPrice: modalPrice,
          sellingPrice: item.sellingPrice,
          type: !old ? "NEW" : oldPrice !== modalPrice ? "PRICE_CHANGED" : "UPDATED"
        });
      }
    }

    const oldCodes = Object.keys(meloCatalog);
    for (const code of oldCodes) {
      if (!next[code]) {
        changed = true;
        changes.push({
          code,
          game: meloCatalog[code]?.game || "",
          name: meloCatalog[code]?.name || code,
          oldPrice: meloCatalog[code]?.meloPrice || null,
          newPrice: null,
          sellingPrice: null,
          type: "REMOVED"
        });
      }
    }

    const removedCodes = { ...(meloCatalogMeta.removedCodes || {}) };
    for (const c of Object.keys(next)) delete removedCodes[c];
    for (const c of oldCodes) {
      if (!next[c]) {
        removedCodes[c] = {
          at: now,
          game: meloCatalog[c]?.game || "",
          name: meloCatalog[c]?.name || c,
          price: Number(meloCatalog[c]?.sellingPrice || meloCatalog[c]?.meloPrice || 0)
        };
      }
    }

    meloCatalog = next;
    saveMeloCatalog();

    meloCatalogMeta = {
      success: true,
      removedCodes,
      lastSyncAt: now,
      reason,
      changed,
      changeCount: changes.length,
      changes: changes.slice(0, 500),
      total: Object.keys(next).length
    };
    saveMeloCatalogMeta();

    if (changed) {
      console.log(`MELOSTORE CATALOG BERUBAH: ${changes.length} perubahan, total ${Object.keys(next).length}`);
    } else {
      console.log(`MELOSTORE CATALOG SYNC OK: ${Object.keys(next).length} produk`);
    }

    return { changed, count: Object.keys(next).length, changes };
  } catch (error) {
    console.error("MELOSTORE CATALOG SYNC:", error.response?.data || error.message);
    meloCatalogMeta = {
      ...meloCatalogMeta,
      success: false,
      lastErrorAt: new Date().toISOString(),
      error: error.message
    };
    saveMeloCatalogMeta();
    return { changed: false, count: Object.keys(meloCatalog).length, error: error.message };
  }
}

