// Menentukan provider mana yang dipakai untuk satu game/produk.
// Urutan pengecekan: field eksplisit dari frontend -> mapping tersimpan ->
// default "vip" (supaya order lama yang belum di-mapping tetap jalan seperti
// sebelumnya, tidak tiba-tiba pindah ke MeloStore tanpa kamu atur).
function resolveProvider(game, product, fields = {}) {
  const explicit = fields?.provider || fields?.topupProvider;
  if (explicit) return String(explicit).toLowerCase();

  const productText = normalizeText(product);
  const gameText = normalizeText(game);
  const mapped =
    providerMap[product] ||
    providerMap[game] ||
    providerMap[productText] ||
    providerMap[gameText];

  if (mapped) return String(mapped).toLowerCase();

  return "vip";
}

