// ---------- Hash password (scrypt) ----------
// Password tidak lagi disimpan polos di data/users.json. Akun lama yang
// masih polos tetap bisa login dan otomatis di-upgrade jadi hash saat login.
function hashPassword(plain) {
  const salt = crypto.randomBytes(16).toString("hex");
  const hash = crypto.scryptSync(String(plain), salt, 64).toString("hex");
  return `scrypt$${salt}$${hash}`;
}

function safeEqualStr(a, b) {
  const ha = crypto.createHash("sha256").update(String(a)).digest();
  const hb = crypto.createHash("sha256").update(String(b)).digest();
  return crypto.timingSafeEqual(ha, hb);
}

function verifyPassword(stored, input) {
  if (typeof stored !== "string" || !stored) return { ok: false, legacy: false };
  if (stored.startsWith("scrypt$")) {
    const parts = stored.split("$");
    if (parts.length !== 3) return { ok: false, legacy: false };
    try {
      const expected = Buffer.from(parts[2], "hex");
      const actual = crypto.scryptSync(String(input), parts[1], expected.length);
      return { ok: expected.length === actual.length && crypto.timingSafeEqual(expected, actual), legacy: false };
    } catch {
      return { ok: false, legacy: false };
    }
  }
  return { ok: safeEqualStr(stored, input), legacy: true };
}

// Akun Dev diisi lewat .env:  DEV_ACCOUNTS=id1:password1,id2:password2
// (id boleh nomor HP atau username; password tidak boleh mengandung koma).
// DEV_USER_ID + DEV_USER_PASS (satu akun) tetap didukung.
function parseDevAccounts() {
  const list = [];
  for (const part of String(process.env.DEV_ACCOUNTS || "").split(",")) {
    const i = part.indexOf(":");
    if (i <= 0) continue;
    const id = part.slice(0, i).trim();
    const pass = part.slice(i + 1).trim();
    if (id && pass) list.push({ id, pass });
  }
  const oneId = String(process.env.DEV_USER_ID || "").trim();
  const onePass = String(process.env.DEV_USER_PASS || "").trim();
  if (oneId && onePass && !list.some((a) => a.id === oneId)) list.push({ id: oneId, pass: onePass });
  return list;
}

function loadUsers() {
  try {
    users = JSON.parse(fs.readFileSync(USERS_FILE, "utf8") || "{}");
  } catch {
    users = {};
  }
}

function saveUsers() {
  fs.writeFileSync(USERS_FILE, JSON.stringify(users, null, 2));
}

// Menghasilkan beberapa kemungkinan bentuk identifier yang sama (nomor HP)
// supaya login/daftar tetap ketemu walau format yang dikirim dari halaman
// beda dikit dengan yang tersimpan (mis. "088277205868" vs "88277205868"
// vs "+6288277205868" vs "6288277205868", atau ada spasi/strip nyelip).
// Ini yang bikin akun Dev sempat kebaca "BELUM TERDAFTAR" padahal sudah
// dipaksa ada di ensureDevUser().
function normalizeIdentifierCandidates(raw) {
  const id = String(raw || "").trim();
  const candidates = new Set();
  if (id) candidates.add(id);

  const digits = id.replace(/[^\d]/g, "");
  if (digits) {
    candidates.add(digits);
    if (digits.startsWith("62")) candidates.add("0" + digits.slice(2));
    else if (digits.startsWith("0")) candidates.add("62" + digits.slice(1));
    else candidates.add("0" + digits);
  }

  return Array.from(candidates);
}

function findUserRecord(rawId) {
  for (const candidate of normalizeIdentifierCandidates(rawId)) {
    if (users[candidate]) return { id: candidate, user: users[candidate] };
  }
  return null;
}

function ensureDevUser() {
  if (!fs.existsSync(USERS_FILE)) fs.writeFileSync(USERS_FILE, "{}");
  loadUsers();

  // Hapus akun placeholder bawaan file lama (password-nya sudah diketahui umum).
  if (users["ISI_DEV_USER_ID"]) delete users["ISI_DEV_USER_ID"];

  const accounts = parseDevAccounts();
  if (!accounts.length) {
    console.warn("PERINGATAN: DEV_ACCOUNTS belum diisi di .env, tidak ada akun Dev yang dibuat.");
  }

  // Akun Dev selalu dipaksa ada sesuai .env, walaupun users.json rusak/terhapus.
  for (const acc of accounts) {
    const existing = findUserRecord(acc.id);
    const key = existing ? existing.id : acc.id;
    users[key] = {
      password: hashPassword(acc.pass),
      isDev: true,
      createdAt: existing?.user?.createdAt || new Date().toISOString()
    };
  }
  saveUsers();
}

ensureDevUser();

app.post("/api/register", (req, res) => {
  const id = String(req.body?.id || req.body?.identifier || "").trim();
  const pass = String(req.body?.pass || req.body?.password || "").trim();

  if (!id || !pass) {
    return res.status(400).json({
      success: false,
      message: "Nomor HP/Email dan Kata Sandi wajib diisi!"
    });
  }

  if (findUserRecord(id)) {
    return res.status(409).json({
      success: false,
      message: "Nomor HP/Email ini SUDAH TERDAFTAR! Silahkan klik Masuk."
    });
  }

  users[id] = { password: hashPassword(pass), isDev: false, createdAt: new Date().toISOString() };
  saveUsers();

  res.json({ success: true, message: "Pendaftaran berhasil." });
});

app.post("/api/login", (req, res) => {
  const id = String(req.body?.id || req.body?.identifier || "").trim();
  const pass = String(req.body?.pass || req.body?.password || "").trim();

  const found = findUserRecord(id);

  if (!found) {
    console.log(`LOGIN GAGAL - id belum terdaftar: "${id}" (dikirim dari halaman)`);
    return res.status(404).json({
      success: false,
      message: "AKUN BELUM TERDAFTAR! Silahkan klik 'Daftar' terlebih dahulu."
    });
  }

  const check = verifyPassword(found.user.password, pass);
  if (!check.ok) {
    return res.status(401).json({
      success: false,
      message: "KATA SANDI SALAH!"
    });
  }
  if (check.legacy) {
    found.user.password = hashPassword(pass);
    saveUsers();
  }

  res.json({
    success: true,
    user: { id: found.id, isDev: Boolean(found.user.isDev) }
  });
});

