function invoice() {
  return "TOPUP-" + Date.now() + "-" +
    crypto.randomBytes(4).toString("hex").toUpperCase();
}

// === STEP 1: Biaya layanan E-Wallet & QRIS (0.7%) ===
// Semua channel pembayaran di toko ini (DANA, GoPay, OVO, ShopeePay, QRIS)
// diproses lewat iPaymu sebagai QRIS, jadi biaya 0.7% berlaku untuk semua.
// Dibulatkan ke ATAS per rupiah supaya toko tidak rugi karena pembulatan.
// Contoh: 100.000 -> fee 700 -> total 100.700. 200.000 -> fee 1.400 -> total 201.400.
const PAYMENT_SERVICE_FEE_RATE = 0.007;
function calcPaymentServiceFee(baseAmount) {
  const n = Number(baseAmount) || 0;
  if (n <= 0) return 0;
  return Math.ceil(n * PAYMENT_SERVICE_FEE_RATE);
}

function sha256(value) {
  return crypto.createHash("sha256").update(value, "utf8").digest("hex");
}

function isConfigured(value) {
  return value &&
    !String(value).startsWith("ISI_") &&
    !String(value).includes("DOMAIN-LU") &&
    !String(value).includes("EMAIL_PENGIRIM");
}

