// ===== FITUR 10: Laporan Penjualan & Keuntungan =====
app.post("/api/dev/report/detailed", (req, res) => {
  const { devPassword, from, to } = req.body || {};
  if (!isValidDevPassword(devPassword)) {
    return res.status(403).json({ success: false, message: "Password Dev salah" });
  }
  try {
    const allOrders = JSON.parse(fs.readFileSync(ORDERS_FILE, "utf8") || "{}");
    const list = Object.values(allOrders).filter(o => o);
    const fromDate = from ? new Date(from) : new Date("2000-01-01");
    const toDate = to ? new Date(to + "T23:59:59") : new Date();

    const filtered = list.filter(o => {
      const d = new Date(o.createdAt || o.created_at || Date.now());
      return d >= fromDate && d <= toDate;
    });

    const successOrders = filtered.filter(o => o.paymentStatus === "SUCCESS" && o.topupStatus === "SUCCESS" && !o.refunded);
    const refundOrders = filtered.filter(o => o.refunded);
    const pendingOrders = filtered.filter(o => o.paymentStatus === "SUCCESS" && o.topupStatus !== "SUCCESS" && !o.refunded);

    const omzet = successOrders.reduce((a, o) => a + Number(o.sellingPrice || o.amount || 0), 0);
    const modal = successOrders.reduce((a, o) => a + Number(o.providerCost || o.modal || o.basePrice || 0), 0);
    const fee = successOrders.reduce((a, o) => a + Number(o.fee || 0), 0);
    const refundAmount = refundOrders.reduce((a, o) => a + Number(o.sellingPrice || 0), 0);
    const modalRefund = refundOrders.filter(o => o.topupStatus === "SUCCESS").reduce((a, o) => a + Number(o.providerCost || 0), 0);

    const keuntunganKotor = omzet - modal;
    const keuntunganBersih = omzet - modal - modalRefund;

    res.json({
      success: true,
      range: { from: fromDate, to: toDate },
      summary: {
        totalTransaksi: filtered.length,
        transaksiSukses: successOrders.length,
        pending: pendingOrders.length,
        refund: refundOrders.length,
        omzet,
        modal,
        fee,
        refundAmount,
        modalRefund,
        keuntunganKotor,
        keuntunganBersih
      },
      orders: filtered.slice(-100).reverse()
    });
  } catch (e) {
    res.status(500).json({ success: false, message: e.message });
  }
});

