try { providerHealthState = JSON.parse(fs.readFileSync(PROVIDER_HEALTH_FILE, "utf8")); } catch {}

function saveProviderHealth() {
  try { fs.writeFileSync(PROVIDER_HEALTH_FILE, JSON.stringify(providerHealthState, null, 2)); } catch {}
}
function applyProviderAutoAvailability(provider, isDown) {
  try {
    const p = String(provider||"").toLowerCase();
    const catalog = p === "melostore" ? meloCatalog : vipCatalog;
    const save = p === "melostore" ? saveMeloCatalog : saveVipCatalog;
    for (const [code,item] of Object.entries(catalog||{})) {
      if (!item || typeof item !== "object") continue;
      if (isDown) {
        if (item.enabled !== false) { item.providerAutoDisabled = true; item.enabled = false; }
      } else if (item.providerAutoDisabled) {
        item.enabled = true; delete item.providerAutoDisabled;
      }
    }
    save();
  } catch(e) { console.error("AUTO PROVIDER AVAILABILITY:",e.message); }
}

async function checkProviderHealth() {
  try {
    if (isConfigured(VIP_API_URL) && isConfigured(VIP_API_KEY)) {
      await axios.post(VIP_API_URL, { key: VIP_API_KEY, sign: vipApiSign(), type: "services" }, { timeout: 8000 });
      providerHealthState.vip = { status: "up", lastCheck: new Date().toISOString(), failCount: 0, lastError: null }; applyProviderAutoAvailability("vip", false);
    }
  } catch (e) {
    providerHealthState.vip.failCount = (providerHealthState.vip.failCount || 0) + 1;
    providerHealthState.vip.status = providerHealthState.vip.failCount >= 2 ? "down" : "unstable"; if(providerHealthState.vip.status === "down") applyProviderAutoAvailability("vip", true);
    providerHealthState.vip.lastCheck = new Date().toISOString();
    providerHealthState.vip.lastError = e.message;
  }
  try {
    if (isConfigured(MELO_API_KEY)) {
      await axios.get(MELO_BASE_URL + "/products", { headers: { "X-API-Key": MELO_API_KEY, "X-Secret-Key": MELO_SECRET_KEY }, timeout: 8000 });
      providerHealthState.melostore = { status: "up", lastCheck: new Date().toISOString(), failCount: 0, lastError: null }; applyProviderAutoAvailability("melostore", false);
    }
  } catch (err) {
    providerHealthState.melostore.failCount = (providerHealthState.melostore.failCount || 0) + 1;
    providerHealthState.melostore.status = providerHealthState.melostore.failCount >= 2 ? "down" : "unstable"; if(providerHealthState.melostore.status === "down") applyProviderAutoAvailability("melostore", true);
    providerHealthState.melostore.lastCheck = new Date().toISOString();
    providerHealthState.melostore.lastError = err.message;
  }
  saveProviderHealth();
}

