// ---------- Validasi password Dev ----------
// Password Dev yang sah = password akun Dev (dari DEV_ACCOUNTS) ATAU password
// Dev global (DEV_PASSWORD di .env / hasil "ganti password" di Panel Dev).
// Tidak ada lagi password Dev bawaan di dalam kode.
const DEV_PASSWORD_FILE = path.join(DATA_DIR, "dev-password.json");
const devPasswordCache = new Map();

function matchesGlobalDevPassword(input) {
  try {
    if (fs.existsSync(DEV_PASSWORD_FILE)) {
      const d = JSON.parse(fs.readFileSync(DEV_PASSWORD_FILE, "utf8"));
      if (d.passwordHash) return verifyPassword(d.passwordHash, input).ok;
      if (d.password) return safeEqualStr(d.password, input);
    }
  } catch {}
  const envPass = String(process.env.DEV_PASSWORD || "");
  return envPass ? safeEqualStr(envPass, input) : false;
}

function isValidDevPassword(input) {
  if (typeof input !== "string" || !input) return false;
  const cacheKey = crypto.createHash("sha256").update(input).digest("hex");
  const cached = devPasswordCache.get(cacheKey);
  if (cached && cached > Date.now()) return true;

  let ok = matchesGlobalDevPassword(input);
  if (!ok) {
    for (const u of Object.values(users)) {
      if (u && u.isDev && verifyPassword(u.password, input).ok) { ok = true; break; }
    }
  }
  if (ok) devPasswordCache.set(cacheKey, Date.now() + 5 * 60 * 1000);
  return ok;
}

function generateDevToken(){
  return require('crypto').randomBytes(32).toString('hex');
}

function verifyDevSession(req){
  const token = req.headers['x-dev-token'] || req.body?.devToken || req.query?.devToken;
  if(!token) return null;
  const sess = devSessions[token];
  if(!sess) return null;
  const ageMinutes = (Date.now() - new Date(sess.lastActive).getTime())/60000;
  if(ageMinutes > 30){
    delete devSessions[token];
    saveDevSessions();
    return null; // auto logout 30 menit
  }
  // update lastActive
  sess.lastActive = new Date().toISOString();
  devSessions[token] = sess;
  saveDevSessions();
  return sess;
}

// PERBAIKAN: fungsi ini sebelumnya bergaya middleware (butuh "next"), padahal
// SEMUA endpoint dev di file ini memanggilnya sebagai `if (!requireDevAuth(req,res)) return;`
// (tanpa next). Sekarang dibuat konsisten: mengembalikan true/false dan
// mengirim response 403 sendiri kalau gagal. Ini juga yang dipakai frontend
// (kirim devToken dari /api/dev/login ATAU devPassword langsung).
function requireDevAuth(req, res){
  const sess = verifyDevSession(req);
  if(sess){ req.devSession = sess; return true; }
  const devPassword = req.body?.devPassword || req.query?.devPassword || req.headers['x-dev-password'];
  if(isValidDevPassword(devPassword)){
    return true;
  }
  res.status(403).json({ success: false, message: "Dev auth required / session expired" });
  return false;
}

app.post("/api/dev/login", (req, res)=>{
  const { password, ip } = req.body||{};
  if(!isValidDevPassword(password)){
    logDevAction("login_failed", req.ip, { reason: "wrong_password" });
    return res.status(403).json({ success: false, message: "Password Dev salah" });
  }
  const currentIp = req.ip;
  const currentUa = req.headers['user-agent']||"";
  const previousSessions = Object.values(devSessions);
  const knownDevice = previousSessions.some(x => x.ip === currentIp && x.userAgent === currentUa);
  const token = generateDevToken();
  devSessions[token] = { token, createdAt: new Date().toISOString(), lastActive: new Date().toISOString(), ip: currentIp, userAgent: currentUa };
  saveDevSessions();
  logDevAction("login_success", req.ip, { token: token.slice(0,8)+"...", newDevice: !knownDevice });
  if (!knownDevice) {
    saveFeatureAlert({type:"dev_login_new_device",ip:currentIp,userAgent:currentUa});
    sendDevEmail("TOPUP STORE - Login Dev dari perangkat/IP baru",`<p>Login Dev baru terdeteksi.</p><p>IP: <b>${escapeHtml(currentIp)}</b><br>Perangkat: ${escapeHtml(currentUa)}</p><p>Waktu: ${escapeHtml(new Date().toLocaleString("id-ID",{timeZone:"Asia/Jakarta"}))}</p>`).catch(()=>{});
  }
  res.json({ success: true, token, expiresInMinutes: 30, newDevice: !knownDevice });
});

