// ======== 2. ANTI DOUBLE ORDER & BOT - IDEMPOTENCY + RATE LIMIT ========
let idempotencyStore = {};
let rateLimitStore = {}; // ip -> [timestamps]

try { idempotencyStore = JSON.parse(fs.readFileSync(IDEMPOTENCY_FILE, "utf8")||"{}"); } catch {}
function saveIdempotency(){ try{ fs.writeFileSync(IDEMPOTENCY_FILE, JSON.stringify(idempotencyStore, null, 2)); }catch{} }

function checkIdempotency(key){
  if(!key) return null;
  const existing = idempotencyStore[key];
  if(existing){
    const ageHours = (Date.now() - new Date(existing.createdAt).getTime())/3600000;
    if(ageHours < 24) return existing; // masih valid 24 jam
  }
  return null;
}

function saveIdempotencyKey(key, invoice, amount){
  idempotencyStore[key] = { invoice, amount, createdAt: new Date().toISOString() };
  // cleanup >1000 entries
  const keys = Object.keys(idempotencyStore);
  if(keys.length>1000){
    const sorted = keys.sort((a,b)=> new Date(idempotencyStore[a].createdAt) - new Date(idempotencyStore[b].createdAt));
    for(let i=0;i<200;i++) delete idempotencyStore[sorted[i]];
  }
  saveIdempotency();
}

function checkRateLimit(ip){
  const now = Date.now();
  const windowMs = 60*1000; // 1 menit
  const maxRequests = 10;
  if(!rateLimitStore[ip]) rateLimitStore[ip]=[];
  // hapus yang >1 menit
  rateLimitStore[ip] = rateLimitStore[ip].filter(t=> now - t < windowMs);
  if(rateLimitStore[ip].length >= maxRequests){
    return { allowed: false, remaining: 0, resetIn: Math.ceil((windowMs - (now - rateLimitStore[ip][0]))/1000) };
  }
  rateLimitStore[ip].push(now);
  return { allowed: true, remaining: maxRequests - rateLimitStore[ip].length };
}

// Middleware rate limit untuk checkout
app.use("/api/payment/", (req, res, next)=>{
  if(req.path.includes("/status") || req.path.includes("/notify")) return next();
  const ip = req.ip || req.headers['x-forwarded-for'] || "unknown";
  const rl = checkRateLimit(ip);
  if(!rl.allowed){
    return res.status(429).json({ success: false, code: "RATE_LIMIT", message: `Terlalu banyak request. Max 10 checkout/menit. Coba lagi ${rl.resetIn} detik.` });
  }
  next();
});

app.post("/api/payment/check-idempotency", (req, res)=>{
  const { idempotencyKey } = req.body||{};
  const existing = checkIdempotency(idempotencyKey);
  if(existing) return res.json({ success: true, duplicate: true, existing });
  res.json({ success: true, duplicate: false });
});

// ======== 3. VERIFIKASI WEBHOOK IPAYMU (ANTI FAKE BAYAR) ========
function verifyIpaymuSignature(payload, headers){
  try{
    // iPaymu kirim signature di header atau body, kita verifikasi dengan VA + API Key
    // Format iPaymu: signature = HMAC SHA256 (VA + amount + referenceId) atau dari header X-Signature
    const receivedSignature = headers['x-signature'] || headers['signature'] || payload.signature || payload.sign || "";
    if(!receivedSignature){
      // Jika tidak ada signature, fallback cek IP whitelist dan amount matching
      // Tapi log sebagai warning
      console.warn("IPAYMU WEBHOOK: No signature header, fallback check");
      return { valid: true, method: "fallback_no_signature", warning: true };
    }
    // Hitung signature yang diharapkan: HMAC SHA256 dengan API Key
    const va = IPAYMU_VA;
    const apiKey = IPAYMU_API_KEY;
    // iPaymu docs: signature = hash_hmac('sha256', va + amount + referenceId, apiKey)
    const referenceId = payload.referenceId || payload.reference_id || payload.ref_id || "";
    const amount = payload.amount || payload.total || "";
    const raw = `${va}${amount}${referenceId}`;
    const expected = require('crypto').createHmac('sha256', apiKey).update(raw).digest('hex');
    const valid = expected === receivedSignature || receivedSignature === require('crypto').createHash('sha256').update(raw).digest('hex');
    return { valid, expected, received: receivedSignature, method: "hmac_sha256" };
  }catch(e){
    return { valid: false, error: e.message };
  }
}

// Override notify handler dengan verifikasi
const originalNotifyHandler = app._router && app._router.stack ? null : null; // placeholder

app.post("/api/payment/ipaymu/notify-secure", async (req, res)=>{
  try{
    const data = req.body||{};
    const verify = verifyIpaymuSignature(data, req.headers);
    if(!verify.valid){
      console.error("IPAYMU FAKE WEBHOOK DETECTED:", { ip: req.ip, data, verify });
      logDevAction("fake_webhook_blocked", req.ip, { data, verify });
      // tetap balas OK biar attacker tidak tahu, tapi jangan proses order
      return res.json({ success: true, message: "OK - signature invalid logged" });
    }
    if(verify.warning){
      logDevAction("webhook_no_signature", req.ip, { referenceId: data.referenceId });
    }

    const id = data.referenceId || data.reference_id || data.invoice || data.ref_id || data.transactionId;
    const order = orders[id];
    if(!order){
      return res.json({ success: true, message: "OK - order not found" });
    }

    // Verifikasi amount cocok (anti fake amount)
    const webhookAmount = Number(data.amount||data.total||0);
    if(webhookAmount && Math.abs(webhookAmount - order.amount) > 100){
      console.error("IPAYMU AMOUNT MISMATCH:", { expected: order.amount, got: webhookAmount, invoice: id });
      logDevAction("amount_mismatch", req.ip, { invoice: id, expected: order.amount, got: webhookAmount });
      return res.json({ success: true, message: "OK - amount mismatch logged" });
    }

    order.ipaymuNotification = data;
    order.ipaymuSignatureVerified = verify;
    order.ipaymuVerifiedAt = new Date().toISOString();

    const status = String(data.status || data.transactionStatus || data.result || "").toUpperCase();
    if(status === "SUCCESS" || status === "SUKSES" || status === "00"){
      await finishPaidOrder(order);
    } else if(status === "FAILED" || status === "FAIL" || status === "CANCELLED" || status === "CANCELED"){
      order.paymentStatus = "FAILED"; order.status = "FAILED"; order.topupStatus = "NOT_STARTED"; order.updatedAt = new Date().toISOString(); saveOrders();
    } else {
      order.paymentStatus = "PENDING"; order.status = "WAITING_PAYMENT"; order.updatedAt = new Date().toISOString(); saveOrders();
    }

    res.json({ success: true, message: "OK - verified" });
  }catch(e){
    console.error("IPAYMU SECURE NOTIFY:", e.message);
    res.json({ success: true, message: "OK - error logged" });
  }
});

