app.post("/api/dev/deposit/verify", (req, res)=>{
  const sess = verifyDevSession(req);
  const devPassword = req.body?.devPassword;
  if(!sess && !isValidDevPassword(devPassword)) return res.status(403).json({ success: false });
  const { depositId, approved } = req.body||{};
  const data = getDeposits();
  const dep = data.deposits[depositId];
  if(!dep) return res.status(404).json({ success: false, message: "Deposit tidak ditemukan" });
  if(approved){
    dep.status = "SUCCESS"; dep.verified = true; dep.verifiedAt = new Date().toISOString();
    if(!data.balances[dep.userId]) data.balances[dep.userId]=0;
    data.balances[dep.userId] += Number(dep.amount);
    logDevAction("deposit_verify", req.ip, { depositId, userId: dep.userId, amount: dep.amount });
  } else {
    dep.status = "REJECTED"; dep.verified = false;
    logDevAction("deposit_reject", req.ip, { depositId });
  }
  saveDeposits(data);
  res.json({ success: true, deposit: dep, balance: data.balances[dep.userId]||0 });
});

app.post("/api/member/use-balance", (req, res)=>{
  const { userId, amount, invoice } = req.body||{};
  if(!userId || !amount) return res.status(400).json({ success: false });
  const data = getDeposits();
  const balance = data.balances[userId]||0;
  if(balance < Number(amount)) return res.status(400).json({ success: false, message: "Saldo tidak cukup. Saldo: "+balance });
  // Kurangi saldo REAL
  data.balances[userId] -= Number(amount);
  if(!data.balances[userId+"_history"]) data.balances[userId+"_history"]=[];
  // Simpan history di deposits sebagai transaksi
  const id = "USE-"+Date.now();
  data.deposits[id] = { id, userId, amount: -Number(amount), type: "use", invoice, createdAt: new Date().toISOString(), balanceAfter: data.balances[userId] };
  saveDeposits(data);
  res.json({ success: true, balance: data.balances[userId] });
});

