/* =========================================================
   CEK NICKNAME GAME - VIP RESELLER / VIPayment
   Endpoint resmi: /api/game-feature
   type: get-nickname
   key: API KEY
   sign: md5(API ID + API KEY)
   Hanya dipakai untuk GAME, bukan aplikasi/e-wallet.
========================================================= */

function extractNickname(data) {
  if (!data) return "";
  const value = data?.data?.nickname ||
    data?.data?.username || // bentuk response MeloStore check-nickname
    data?.nickname ||
    data?.username ||
    data?.name ||
    (typeof data?.data === "string" ? data.data : "");
  return typeof value === "string" ? value.trim() : "";
}

function extractValid(data) {
  // result === true -> VIP Reseller, success === true -> MeloStore
  return data?.result === true || data?.success === true || Boolean(extractNickname(data));
}

async function vipRequest(payload) {
  if (!isConfigured(VIP_API_KEY)) {
    throw new Error("Kunci API VIP Reseller belum diisi di server.js");
  }

  const body = {
    key: VIP_API_KEY,
    sign: vipApiSign(),
    ...payload
  };

  const response = await axios.post(
    VIP_API_URL,
    body,
    {
      headers: { "Content-Type": "application/json" },
      timeout: 30000
    }
  );

  return response.data || {};
}

function normalizeText(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

async function findVipGameServiceCode(game, product, fields = {}) {
  const suppliedCode =
    fields?.vipServiceCode ||
    fields?.serviceCode ||
    fields?.service_code ||
    fields?.code ||
    fields?.service;

  // Bila HTML sudah mengirim kode layanan VIP, gunakan langsung.
  if (suppliedCode && String(suppliedCode).trim()) {
    return String(suppliedCode).trim();
  }

  // Cek dulu di data/vip-service-codes.json (mapping manual yang kamu isi
  // dari dashboard VIP Reseller). Ini cara paling stabil karena tidak
  // bergantung ke pencarian nama otomatis yang gampang meleset.
  const productText0 = normalizeText(product);
  const gameText0 = normalizeText(game);
  const mapped =
    vipServiceCodes[product] ||
    vipServiceCodes[game] ||
    vipServiceCodes[productText0] ||
    vipServiceCodes[gameText0];
  if (mapped && String(mapped).trim()) {
    return String(mapped).trim();
  }

  // Ambil daftar layanan VIP dan cari kode berdasarkan nama game/produk.
  const serviceResult = await vipRequest({
    type: "services",
    filter_game: String(game || ""),
    filter_status: "available"
  });

  const list = Array.isArray(serviceResult?.data) ? serviceResult.data : [];
  const productText = normalizeText(product);
  const gameText = normalizeText(game);

  if (productText) {
    const exact = list.find(item =>
      normalizeText(item?.name) === productText ||
      normalizeText(item?.code) === productText
    );
    if (exact?.code) return String(exact.code);

    const partial = list.find(item => {
      const name = normalizeText(item?.name);
      return name && (name.includes(productText) || productText.includes(name));
    });
    if (partial?.code) return String(partial.code);
  }

  // Jika hanya satu layanan tersedia untuk game tersebut, pakai layanan itu.
  if (list.length === 1 && list[0]?.code) {
    return String(list[0].code);
  }

  // Beberapa konfigurasi mengirim kode langsung sebagai product.
  if (/^[A-Z0-9_.:-]{3,}$/.test(String(product || ""))) {
    return String(product).trim();
  }

  throw new Error(
    `Kode layanan VIP untuk produk "${product || game || ""}" belum ditemukan. ` +
    `Tambahkan mapping-nya di data/vip-service-codes.json (key = nama produk persis seperti ` +
    `dikirim dari halaman, value = kode layanan asli dari dashboard VIP Reseller), ` +
    `atau cek dulu daftar kode aslinya lewat GET /api/vip-reseller/products?game=${encodeURIComponent(game || "")}.`
  );
}

async function checkGameAccount({ game, product, uid, zoneid, fields = {} }) {
  if (!game || !uid) throw new Error("Game dan ID wajib diisi");

  const provider = resolveProvider(game, product, fields);

  if (provider === "melostore" || provider === "melo") {
    const gameCode = await findMeloGameCode(game, fields);
    return meloRequest("POST", "/api/v1/h2h/check-nickname", {
      game_code: gameCode,
      customer_target: String(uid),
      customer_target_zone: String(zoneid || "")
    });
  }

  const code = await findVipGameServiceCode(game, product, fields);

  const payload = {
    type: "get-nickname",
    code,
    target: String(uid),
    additional_target: String(zoneid || "")
  };

  return vipRequest(payload);
}

async function handleGameAccountCheck(req, res) {
  try {
    const { game, product, uid, userId, target, zoneid, zoneId, fields = {} } = req.body || {};
    const actualUid = uid || userId || target;
    const actualZone = zoneid || zoneId || "";

    if (!game || !actualUid) {
      return res.status(400).json({
        success: false,
        valid: false,
        message: "Game dan ID wajib diisi"
      });
    }

    const result = await checkGameAccount({
      game,
      product,
      uid: actualUid,
      zoneid: actualZone,
      fields
    });

    const nickname = extractNickname(result);
    const valid = extractValid(result) && Boolean(nickname);

    if (!valid) {
      return res.status(404).json({
        success: false,
        valid: false,
        nickname: "",
        message: result?.message || "ID akun tidak ditemukan",
        raw: result
      });
    }

    return res.json({
      success: true,
      valid: true,
      nickname,
      game,
      uid: String(actualUid),
      zoneid: actualZone,
      raw: result
    });
  } catch (error) {
    console.error("VIP GAME ACCOUNT CHECK:", error.response?.data || error.message);
    return res.status(502).json({
      success: false,
      valid: false,
      message: error.message || "Gagal mengecek nama akun melalui VIP Reseller."
    });
  }
}

