/* =========================================================
   KATALOG LIVE VIP RESELLER
   Semua produk yang tampil di website berasal dari service VIP
   dengan status AVAILABLE. Kode + harga tidak ditebak/hardcode.
========================================================= */
app.get("/api/vip-reseller/catalog", async (req, res) => {
  try {
    // Cache server-side, refresh berkala agar harga/kode VIP selalu mengikuti provider.
    if (!Object.keys(vipCatalog).length || req.query.refresh === "1") {
      await refreshVipCatalog(req.query.refresh === "1" ? "manual" : "first-load");
    }

    const products = Object.values(vipCatalog)
      .filter(x => String(x.status).toLowerCase() === "available")
      .map(normalizeVipCatalogItem);

    res.set("Cache-Control", "no-store");
    res.json({
      success: true,
      priceLevel: String(process.env.VIP_PRICE_LEVEL || "basic").toLowerCase(),
      lastSyncAt: vipCatalogMeta.lastSyncAt || null,
      changed: Boolean(vipCatalogMeta.changed),
      changeCount: Number(vipCatalogMeta.changeCount || 0),
      products,
      unavailable: Object.entries(vipCatalogMeta.removedCodes || {}).map(([code, v]) => ({
        code,
        game: v?.game || "",
        name: v?.name || code,
        price: Number(v?.price || 0),
        since: v?.at || null
      }))
    });
  } catch (error) {
    console.error("VIP LIVE CATALOG:", error.response?.data || error.message);
    res.status(502).json({ success: false, message: error.message || "Gagal mengambil katalog VIP Reseller" });
  }
});

