// Dev bisa mengubah HARGA JUAL website per service code.
// vipPrice tetap disimpan sebagai harga asli VIP; sellingPrice adalah harga web.
app.post("/api/dev/vip-price", (req, res) => {
  try {
    const devId = String(req.body?.devId || req.body?.id || "").trim();
    const devPass = String(req.body?.devPass || req.body?.password || "").trim();
    const code = String(req.body?.code || "").trim();
    const price = Number(req.body?.price);

    const dev = findUserRecord(devId);
    if (!dev?.user?.isDev || !verifyPassword(dev.user.password, devPass).ok) {
      return res.status(401).json({ success: false, message: "Akses Dev ditolak." });
    }
    if (!code) return res.status(400).json({ success: false, message: "Kode VIP wajib diisi." });
    if (!(price > 0)) return res.status(400).json({ success: false, message: "Harga harus lebih dari 0." });

    const item = vipCatalog[code];
    if (!item) return res.status(404).json({ success: false, message: "Kode VIP tidak ditemukan di katalog aktif." });

    item.sellingPrice = Math.round(price);
    item.priceOverridden = true;
    item.updatedAt = new Date().toISOString();
    vipCatalogMeta.changed = true;
    vipCatalogMeta.changeCount = Number(vipCatalogMeta.changeCount || 0) + 1;
    vipCatalogMeta.changes = [{
      code: item.code,
      game: item.game,
      name: item.name,
      oldVipPrice: item.vipPrice,
      vipPrice: item.vipPrice,
      sellingPrice: item.sellingPrice,
      type: "WEB_PRICE_CHANGED_BY_DEV"
    }, ...(vipCatalogMeta.changes || [])].slice(0, 500);
    saveVipCatalog();
    saveVipCatalogMeta();

    res.json({ success: true, message: `Harga ${item.name} berhasil diubah.`, product: normalizeVipCatalogItem(item) });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

// Hapus override harga Dev -> harga website kembali mengikuti harga VIP.
app.post("/api/dev/vip-price/reset", (req, res) => {
  try {
    const devId = String(req.body?.devId || req.body?.id || "").trim();
    const devPass = String(req.body?.devPass || req.body?.password || "").trim();
    const code = String(req.body?.code || "").trim();
    const dev = findUserRecord(devId);
    if (!dev?.user?.isDev || !verifyPassword(dev.user.password, devPass).ok) {
      return res.status(401).json({ success: false, message: "Akses Dev ditolak." });
    }
    if (!vipCatalog[code]) return res.status(404).json({ success: false, message: "Kode VIP tidak ditemukan." });
    vipCatalog[code].sellingPrice = vipCatalog[code].vipPrice;
    vipCatalog[code].priceOverridden = false;
    vipCatalog[code].updatedAt = new Date().toISOString();
    saveVipCatalog();
    res.json({ success: true, message: "Harga website dikembalikan ke harga VIP.", product: normalizeVipCatalogItem(vipCatalog[code]) });
  } catch (error) {
    res.status(500).json({ success: false, message: error.message });
  }
});

/* =========================================================
   VIP RESELLER
========================================================= */

function extractVipTrxId(data) {
  return String(
    data?.data?.trxid ||
    data?.data?.trx_id ||
    data?.data?.transaction_id ||
    data?.data?.transactionId ||
    data?.trxid ||
    data?.trx_id ||
    data?.transaction_id ||
    data?.transactionId ||
    ""
  ).trim();
}

function vipResponseStatus(data) {
  const candidates = [
    data?.status,
    data?.data?.status,
    data?.data?.transaction_status,
    data?.data?.transactionStatus,
    data?.message,
    data?.data?.message,
    data?.code,
    data?.data?.code
  ].filter(v => v !== undefined && v !== null && v !== "");

  const text = candidates.map(v => String(v).toUpperCase()).join(" ");
  const result = data?.result;

  if (result === false) return "FAILED";
  if (result === true && !text) return "PROCESSING";

  if (/SUCCESS|SUKSES|BERHASIL|DONE|COMPLETED/.test(text)) return "SUCCESS";
  if (/FAILED|FAIL|GAGAL|ERROR|CANCELLED|CANCELED/.test(text)) return "FAILED";
  if (/PROCESS|PENDING|WAIT|ANTRI|QUEUE/.test(text)) return "PROCESSING";

  return result === true ? "PROCESSING" : "PROCESSING";
}

async function sendVipTopup(order) {
  if (!isConfigured(VIP_API_URL) || !isConfigured(VIP_API_KEY)) {
    return {
      success: false,
      status: "PENDING",
      message: "VIP Reseller belum dikonfigurasi"
    };
  }

  try {
    // BUG LAMA: kode layanan VIP yang berhasil ditemukan (lewat mapping di
    // vip-service-codes.json atau pencarian nama ke API VIP Reseller) cuma
    // dipakai pas CEK NICKNAME, tidak pernah dipakai lagi pas ORDER TOP UP
    // beneran dikirim - order lama cuma kirim order.product/order.game apa
    // adanya sebagai "service", yang belum tentu sama dengan kode asli VIP
    // Reseller. Sekarang resolve dengan fungsi yang sama supaya konsisten.
    let serviceCode =
      order.serviceCode ||
      order.fields?.vipServiceCode ||
      order.fields?.serviceCode;

    if (!serviceCode) {
      serviceCode = await findVipGameServiceCode(
        order.game,
        order.product,
        order.fields || {}
      );
      order.serviceCode = serviceCode;
    }

    const payload = {
      type: "order",
      service: serviceCode,
      data_no: order.target || order.userId || "",
      data_zone: order.zoneId || "",
      post_additional_data: order.fields?.post_additional_data || ""
    };

    const data = await vipRequest(payload);
    const status = vipResponseStatus(data);
    const trxId = extractVipTrxId(data);

    if (status === "SUCCESS") {
      return { success: true, status: "SUCCESS", trxId, data };
    }

    if (status === "FAILED") {
      return { success: false, status: "FAILED", trxId, data };
    }

    return { success: false, status: "PENDING", trxId, data };
  } catch (error) {
    console.error("VIP TOPUP:", error.response?.data || error.message);
    return {
      success: false,
      status: "PENDING",
      message: error.response?.data || error.message
    };
  }
}

/* =========================================================
   MELOSTORE H2H
   Dokumentasi resmi: https://h2h.melostore.id/docs
   Otentikasi: header X-API-Key + X-Secret-Key (bukan sign md5 seperti VIP).
   BARU DIPAKAI UNTUK KATEGORI GAME (belum aplikasi/PPOB), sesuai instruksi.
========================================================= */

async function meloRequest(method, urlPath, body) {
  if (!isConfigured(MELO_API_KEY) || !isConfigured(MELO_SECRET_KEY)) {
    throw new Error("Kunci API MeloStore belum diisi di server.js");
  }

  const headers = {
    "X-API-Key": MELO_API_KEY,
    "X-Secret-Key": MELO_SECRET_KEY,
    "Content-Type": "application/json"
  };

  const url = MELO_BASE_URL + urlPath;

  const response = method === "GET"
    ? await axios.get(url, { headers, timeout: 30000 })
    : await axios.post(url, body || {}, { headers, timeout: 30000 });

  return response.data || {};
}

// Cari game_code MeloStore (mis. "mobile-legends", "free-fire") dari nama
// game yang dikirim halaman. Dicek dulu mapping manual di
// data/melo-game-codes.json, baru fallback slug otomatis.
async function findMeloGameCode(game, fields = {}) {
  const supplied = fields?.meloGameCode || fields?.game_code;
  if (supplied && String(supplied).trim()) return String(supplied).trim();

  const gameText = normalizeText(game);
  const mapped = meloGameCodes[game] || meloGameCodes[gameText];
  if (mapped && String(mapped).trim()) return String(mapped).trim();

  // Fallback: ubah "Mobile Legends" -> "mobile-legends"
  return gameText.replace(/\s+/g, "-");
}

// Cari sku_code MeloStore (mis. "ml-id-1045") dari nama produk yang dikirim
// halaman. Dicek dulu mapping manual di data/melo-service-codes.json, baru
// fallback ke pencarian nama di katalog yang sudah di-cache.
async function findMeloSkuCode(game, product, fields = {}) {
  const supplied =
    fields?.meloSkuCode ||
    fields?.skuCode ||
    fields?.sku_code ||
    fields?.code;

  if (supplied && String(supplied).trim()) return String(supplied).trim();

  const productText0 = normalizeText(product);
  const gameText0 = normalizeText(game);
  const mapped =
    meloServiceCodes[product] ||
    meloServiceCodes[game] ||
    meloServiceCodes[productText0] ||
    meloServiceCodes[gameText0];
  if (mapped && String(mapped).trim()) return String(mapped).trim();

  if (!Object.keys(meloCatalog).length) {
    await refreshMeloCatalog("lookup");
  }

  const list = Object.values(meloCatalog);
  const productText = normalizeText(product);

  if (productText) {
    const exact = list.find(item =>
      normalizeText(item?.name) === productText ||
      normalizeText(item?.code) === productText
    );
    if (exact?.code) return String(exact.code);

    const partial = list.find(item => {
      const name = normalizeText(item?.name);
      return name && (name.includes(productText) || productText.includes(name));
    });
    if (partial?.code) return String(partial.code);
  }

  throw new Error(
    `Kode SKU MeloStore untuk produk "${product || game || ""}" belum ditemukan. ` +
    `Tambahkan mapping-nya di data/melo-service-codes.json (key = nama produk persis seperti ` +
    `dikirim dari halaman, value = sku_code asli dari dashboard MeloStore), ` +
    `atau cek dulu daftar SKU aslinya lewat GET /api/melostore/products?game=${encodeURIComponent(game || "")}.`
  );
}

function extractMeloTrxId(data) {
  return String(data?.data?.id || "").trim();
}

function meloResponseStatus(data) {
  if (data?.success === false) return "FAILED";

  const status = String(data?.data?.status || "").toLowerCase();
  if (status === "success") return "SUCCESS";
  if (["failed", "error", "cancelled", "canceled"].includes(status)) return "FAILED";
  // "pending" / "processing" / status lain -> masih diproses
  return "PROCESSING";
}

async function sendMeloTopup(order) {
  if (!isConfigured(MELO_API_KEY) || !isConfigured(MELO_SECRET_KEY)) {
    return {
      success: false,
      status: "PENDING",
      message: "MeloStore belum dikonfigurasi"
    };
  }

  try {
    let skuCode =
      order.serviceCode ||
      order.fields?.meloSkuCode ||
      order.fields?.skuCode ||
      order.fields?.sku_code;

    if (!skuCode) {
      skuCode = await findMeloSkuCode(order.game, order.product, order.fields || {});
      order.serviceCode = skuCode;
    }

    // buyer_trx_id wajib unik - invoice kita sudah unik per transaksi.
    const payload = {
      sku_code: skuCode,
      customer_target: order.target || order.userId || "",
      customer_target_zone: order.zoneId || "",
      buyer_trx_id: order.invoice
    };

    const data = await meloRequest("POST", "/api/v1/h2h/transaction", payload);
    const status = meloResponseStatus(data);
    const trxId = extractMeloTrxId(data);

    if (status === "SUCCESS") {
      return { success: true, status: "SUCCESS", trxId, data };
    }
    if (status === "FAILED") {
      return { success: false, status: "FAILED", trxId, data };
    }
    return { success: false, status: "PENDING", trxId, data };
  } catch (error) {
    console.error("MELOSTORE TOPUP:", error.response?.data || error.message);
    return {
      success: false,
      status: "PENDING",
      message: error.response?.data || error.message
    };
  }
}

async function checkMeloStatus(trxId) {
  return meloRequest("GET", `/api/v1/h2h/transaction/${encodeURIComponent(trxId)}`);
}

// Dispatcher umum: kirim top up ke provider yang benar (VIP Reseller atau
// MeloStore) berdasarkan mapping di data/provider-map.json. Ini titik
// tunggal supaya order TIDAK PERNAH tercampur/tertukar antar provider -
// setiap order "mengunci" provider-nya sendiri di field order.provider
// begitu ditentukan pertama kali.
async function sendTopup(order) {
  if (!order.provider) {
    order.provider = resolveProvider(order.game, order.product, order.fields || {});
  }
  const result = order.provider === "melostore" || order.provider === "melo"
    ? await sendMeloTopup(order)
    : await sendVipTopup(order);
  recordOrderCost(order);
  return result;
}

// Lihat/atur mapping "nama produk/game" -> provider ("vip" / "melostore").
app.get("/api/provider-map", (req, res) => {
  if (!requireDevAuth(req, res)) return;
  res.json({ success: true, map: providerMap });
});

app.post("/api/provider-map", (req, res) => {
  if (!requireDevAuth(req, res)) return;
  const { key, provider } = req.body || {};
  const p = String(provider || "").toLowerCase();

  if (!key || !String(key).trim()) {
    return res.status(400).json({ success: false, message: "Isi 'key' (nama game/produk persis seperti dikirim dari halaman)" });
  }
  if (!["vip", "melostore"].includes(p)) {
    return res.status(400).json({ success: false, message: "'provider' harus 'vip' atau 'melostore'" });
  }

  providerMap[String(key)] = p;
  saveProviderMap();
  res.json({ success: true, map: providerMap });
});

