/* =========================================================
   iPaymu
   Dipakai untuk SEMUA metode (label: DANA/GoPay/OVO/ShopeePay/QRIS).
   iPaymu resminya cuma punya channel: va, banktransfer, cstore,
   cod, qris (tidak ada channel "dana"/"ovo"/"gopay"/"shopeepay"
   terpisah). Jadi semua metode e-wallet di atas cuma LABEL tampilan;
   yang benar-benar dibuat ke iPaymu selalu SATU QRIS lewat Direct
   Payment, karena QRIS bisa dipindai e-wallet apapun (termasuk DANA).
   'method' cuma dipakai untuk label yang ditampilkan ke customer.
========================================================= */

function ipaymuTimestamp() {
  // iPaymu minta format YYYYMMDDHHmmss (bukan Unix timestamp).
  // Ref resmi: https://docs.ipaymu.com/en/docs
  const now = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  return (
    now.getFullYear().toString() +
    pad(now.getMonth() + 1) +
    pad(now.getDate()) +
    pad(now.getHours()) +
    pad(now.getMinutes()) +
    pad(now.getSeconds())
  );
}

function iPaymuHeaders(method, bodyObject) {
  const timestamp = ipaymuTimestamp();

  // Signature iPaymu v2: HMAC-SHA256( METHOD:VA:sha256(body):APIKEY, APIKEY ).
  // Ref resmi: https://docs.ipaymu.com/en/docs/signature
  const bodyHash = sha256(JSON.stringify(bodyObject)).toLowerCase();
  const stringToSign = `${method.toUpperCase()}:${IPAYMU_VA}:${bodyHash}:${IPAYMU_API_KEY}`;

  const signature = crypto
    .createHmac("sha256", IPAYMU_API_KEY)
    .update(stringToSign)
    .digest("hex");

  return {
    "Content-Type": "application/json",
    "va": IPAYMU_VA,
    "signature": signature,
    "timestamp": timestamp
  };
}

// ITEM 9: cek ketersediaan produk sebelum pembayaran dibuat.
// Hanya membaca katalog cache (tanpa request ke provider) dan "fail-open":
// kalau kode produk tidak dikenali, checkout tetap jalan seperti biasa.
// Cari kode katalog (VIP / MeloStore) dari data order, tanpa request ke provider.
function resolveCatalogCode(game, product, fields = {}, providerHint = "", knownCode = "") {
  const provider = providerHint || resolveProvider(game, product, fields || {});
  const isMelo = provider === "melostore" || provider === "melo";
  let code = knownCode || (isMelo
    ? (fields?.meloSkuCode || fields?.skuCode || fields?.sku_code || fields?.code)
    : (fields?.vipServiceCode || fields?.serviceCode || fields?.service_code || fields?.code || fields?.service));
  if (!code) {
    const map = isMelo ? meloServiceCodes : vipServiceCodes;
    code = map[product] || map[game] || map[normalizeText(product)] || map[normalizeText(game)];
  }
  return { isMelo, code: String(code || "").trim() };
}

function checkProductAvailability(game, product, fields = {}) {
  try {
    const { isMelo, code } = resolveCatalogCode(game, product, fields);
    if (!code) return { ok: true };
    const catalog = isMelo ? meloCatalog : vipCatalog;
    const removed = (isMelo ? meloCatalogMeta : vipCatalogMeta).removedCodes || {};

    const item = catalog[code];
    if (item && item.enabled === false) {
      return { ok: false, code, message: "Produk ini sedang tidak tersedia. Silakan pilih nominal lain." };
    }
    if (item) {
      const st = String(item.status || "available").toLowerCase();
      if (st !== "available" && st !== "active") {
        return { ok: false, code, message: "Produk ini sedang tidak tersedia. Silakan pilih nominal lain." };
      }
      return { ok: true, code };
    }
    if (removed[code]) {
      return { ok: false, code, message: "Produk ini sedang tidak tersedia. Silakan pilih nominal lain." };
    }
    return { ok: true, code };
  } catch {
    return { ok: true };
  }
}

// ITEM 10: catat harga modal provider di order saat top up dikirim, supaya
// laporan untung memakai harga modal yang berlaku saat transaksi (bukan harga hari ini).
function recordOrderCost(order) {
  try {
    if (Number(order.costPrice) > 0) return;
    const { isMelo, code } = resolveCatalogCode(order.game, order.product, order.fields || {}, order.provider, order.serviceCode);
    const item = (isMelo ? meloCatalog : vipCatalog)[code];
    const cost = Number(isMelo ? item?.meloPrice : item?.vipPrice);
    if (cost > 0) {
      order.costPrice = cost;
      order.costProvider = isMelo ? "melostore" : "vip";
      order.costRecordedAt = new Date().toISOString();
    }
  } catch { /* pencatatan modal tidak boleh mengganggu top up */ }
}

/* =========================================================
   FITUR LANJUTAN: PROMO SERVER, BACKUP, MAINTENANCE, FLASH SALE,
   SCHEDULED PROMO, PAYMENT REMINDER, EMERGENCY STOP & REFUND
========================================================= */
function readJsonSafe(file, fallback) { try { return JSON.parse(fs.readFileSync(file, "utf8") || ""); } catch { return fallback; } }
function writeJsonSafe(file, data) { fs.writeFileSync(file, JSON.stringify(data, null, 2)); }
function normFeatureText(v) { return String(v || "").trim().toLowerCase(); }
function matchesScope(item, game, product) {
  const g = normFeatureText(game), p = normFeatureText(product);
  const games = Array.isArray(item?.games) ? item.games.map(normFeatureText).filter(Boolean) : [];
  const products = Array.isArray(item?.products) ? item.products.map(normFeatureText).filter(Boolean) : [];
  const gameOk = !games.length || games.includes(g);
  const productOk = !products.length || products.includes(p);
  return gameOk && productOk;
}
function withinWindow(item, now = Date.now()) {
  const start = item?.startAt ? new Date(item.startAt).getTime() : -Infinity;
  const end = item?.endAt ? new Date(item.endAt).getTime() : Infinity;
  return Number.isFinite(start) && now < start ? false : Number.isFinite(end) && now > end ? false : true;
}
function checkoutControl() { return readJsonSafe(CHECKOUT_CONTROL_FILE, { emergencyStop:false, reason:"" }); }
function maintenanceMessage(game, product) {
  const m = readJsonSafe(MAINTENANCE_FILE, { games:{}, products:{} });
  const g = normFeatureText(game), p = normFeatureText(product);
  const entry = m.products?.[product] || m.products?.[p] || m.games?.[game] || m.games?.[g];
  if (!entry) return null;
  if (entry === true) return "Produk/game sedang maintenance.";
  if (entry.enabled === false) return null;
  if (entry.enabled || entry.maintenance) return entry.message || "Produk/game sedang maintenance. Silakan coba lagi nanti.";
  return null;
}
function getActiveDiscount({ game, product, promoCode, baseAmount, userId = "" }) {
  const now = Date.now();
  let discount = 0, applied = [];
  const flash = readJsonSafe(FLASH_SALE_FILE, { sales:[] }).sales || [];
  for (const sale of flash) {
    if (!sale?.enabled || !withinWindow(sale, now) || !matchesScope(sale, game, product)) continue;
    const min = Number(sale.minAmount || 0);
    if (Number(baseAmount) < min) continue;
    const value = sale.type === "percent" ? Number(baseAmount) * Number(sale.value || 0) / 100 : Number(sale.value || 0);
    if (value > 0) { discount += value; applied.push({ type:"flash_sale", name:sale.name||"Flash Sale", amount:value }); }
  }
  const scheduled = readJsonSafe(SCHEDULED_PROMO_FILE, { promos:[] }).promos || [];
  for (const promo of scheduled) {
    if (!promo?.enabled || !withinWindow(promo, now) || !matchesScope(promo, game, product)) continue;
    const min = Number(promo.minAmount || 0);
    if (Number(baseAmount) < min) continue;
    const value = promo.type === "percent" ? Number(baseAmount) * Number(promo.value || 0) / 100 : Number(promo.value || 0);
    if (value > 0) { discount += value; applied.push({ type:"scheduled", name:promo.name||"Promo Terjadwal", amount:value }); }
  }
  if (promoCode) {
    const db = readJsonSafe(PROMO_FILE, { codes:{} });
    const code = String(promoCode).trim().toUpperCase();
    const c = db.codes?.[code];
    if (!c || c.enabled === false) return { error:"Kode promo tidak valid atau sudah dinonaktifkan." };
    if (!withinWindow(c, now)) return { error:"Kode promo belum aktif atau sudah berakhir." };
    if (!matchesScope(c, game, product)) return { error:"Kode promo tidak berlaku untuk produk/game ini." };
    if (Number(baseAmount) < Number(c.minAmount || 0)) return { error:`Minimal transaksi untuk kode ${code} adalah Rp ${Number(c.minAmount||0).toLocaleString("id-ID")}.` };
    if (c.maxUses != null && Number(c.used || 0) >= Number(c.maxUses)) return { error:"Batas penggunaan kode promo sudah habis." };
    const uid = String(userId || "").trim();
    const perUserLimit = Math.max(0, Number(c.perUserLimit ?? (c.onePerAccount ? 1 : 0)));
    if (perUserLimit > 0 && uid) {
      const usedByUser = Number(c.usageByUser?.[uid] || 0);
      if (usedByUser >= perUserLimit) return { error:"Kode promo ini sudah pernah digunakan oleh akun ini." };
    }
    let value = c.type === "percent" ? Number(baseAmount) * Number(c.value || 0) / 100 : Number(c.value || 0);
    if (Number(c.maxDiscount) > 0) value = Math.min(value, Number(c.maxDiscount));
    if (value > 0) discount += value;
    applied.push({ type:"code", code, name:c.name||code, amount:value });
  }
  discount = Math.max(0, Math.min(Number(baseAmount), Math.round(discount)));
  return { discount, applied };
}
function consumePromoCode(order) {
  const code = order?.promo?.code;
  if (!code || order.promoConsumedAt) return;
  const db = readJsonSafe(PROMO_FILE, { codes:{} });
  const c = db.codes?.[code];
  if (!c) return;
  const uid = String(order.userId || "").trim();
  if (c.maxUses != null && Number(c.used || 0) >= Number(c.maxUses)) return;
  c.used = Number(c.used || 0) + 1;
  if (uid) {
    c.usageByUser = c.usageByUser && typeof c.usageByUser === "object" ? c.usageByUser : {};
    c.usageByUser[uid] = Number(c.usageByUser[uid] || 0) + 1;
  }
  c.lastUsedAt = new Date().toISOString();
  order.promoConsumedAt = c.lastUsedAt;
  writeJsonSafe(PROMO_FILE, db);
}

function createBackup(label = "manual") {
  try {
    const stamp = new Date().toISOString().replace(/[:.]/g,"-");
    const dir = path.join(BACKUP_DIR, `${stamp}-${String(label).replace(/[^a-z0-9_-]/gi,"_")}`);
    fs.mkdirSync(dir, { recursive:true });
    const files = fs.readdirSync(DATA_DIR).filter(f => f.endsWith(".json"));
    for (const f of files) fs.copyFileSync(path.join(DATA_DIR,f), path.join(dir,f));
    const manifest = { createdAt:new Date().toISOString(), label, files };
    writeJsonSafe(path.join(dir,"manifest.json"), manifest);
    const dirs = fs.readdirSync(BACKUP_DIR, { withFileTypes:true }).filter(x=>x.isDirectory()).sort((a,b)=>a.name.localeCompare(b.name));
    while (dirs.length > 30) { const old = dirs.shift(); fs.rmSync(path.join(BACKUP_DIR,old.name), {recursive:true,force:true}); }
    return { success:true, name:path.basename(dir), createdAt:manifest.createdAt };
  } catch (e) { console.error("BACKUP:", e.message); return { success:false, message:e.message }; }
}
function listBackups() {
  if (!fs.existsSync(BACKUP_DIR)) return [];
  return fs.readdirSync(BACKUP_DIR,{withFileTypes:true}).filter(x=>x.isDirectory()).map(x=>{
    const m=readJsonSafe(path.join(BACKUP_DIR,x.name,"manifest.json"),{}); return { name:x.name, ...m };
  }).sort((a,b)=>String(a.createdAt).localeCompare(String(b.createdAt)));
}
function restoreBackup(name) {
  if (!/^[a-z0-9_.-]+$/i.test(String(name||""))) throw new Error("Nama backup tidak valid");
  const dir=path.join(BACKUP_DIR,String(name));
  if (!fs.existsSync(dir)) throw new Error("Backup tidak ditemukan");
  createBackup("before-restore");
  const files=fs.readdirSync(dir).filter(f=>f.endsWith(".json") && f!=="manifest.json");
  for(const f of files) fs.copyFileSync(path.join(dir,f),path.join(DATA_DIR,f));
  return { restored:name, files };
}
function saveFeatureAlert(alert) {
  const db=readJsonSafe(DEV_ALERT_FILE,{alerts:[]}); db.alerts.push({ ...alert, at:new Date().toISOString() }); db.alerts=db.alerts.slice(-500); writeJsonSafe(DEV_ALERT_FILE,db);
}
async function sendDevEmail(subject, html) {
  const to = process.env.DEV_EMAIL || SMTP_USER;
  if (!isConfigured(to)) return { success:false, message:"DEV_EMAIL belum dikonfigurasi" };
  try { const result=await getMailer().sendMail({from:MAIL_FROM,to,subject,html}); return {success:true,messageId:result.messageId}; } catch(e) { console.error("DEV EMAIL:",e.message); return {success:false,message:e.message}; }
}
async function sendPaymentReminder(order) {
  if (!order?.email || !isConfigured(order.email)) return;
  if (order.paymentStatus !== "PENDING" || order.status !== "WAITING_PAYMENT") return;
  if (order.expiresAt && Date.now() > Number(order.expiresAt)) return;
  order.paymentReminderCount = Number(order.paymentReminderCount || 0) + 1;
  order.lastPaymentReminderAt = new Date().toISOString();
  try { await getMailer().sendMail({from:MAIL_FROM,to:order.email,subject:`Pengingat pembayaran ${order.invoice} - TOPUP STORE`,html:`<p>Halo, pembayaran untuk <b>${escapeHtml(order.invoice)}</b> masih menunggu.</p><p>Total: <b>${rupiah(order.amount)}</b></p><p>Silakan lanjutkan pembayaran sebelum transaksi kedaluwarsa.</p>`}); order.paymentReminderSentAt=order.lastPaymentReminderAt; } catch(e) { console.error("PAYMENT REMINDER:",e.message); }
  saveOrders();
}
function userRefundRequestPath() { return REFUND_FILE; }
function refundDb() { return readJsonSafe(REFUND_FILE,{requests:{}}); }
function saveRefundDb(db) { writeJsonSafe(REFUND_FILE,db); }
function refundRequestId() { return "REF-"+Date.now()+"-"+crypto.randomBytes(3).toString("hex").toUpperCase(); }
function feedbackDb() { return readJsonSafe(FEEDBACK_FILE,{feedbacks:{}}); }
function saveFeedbackDb(db) { writeJsonSafe(FEEDBACK_FILE,db); }
function feedbackId() { return "FB-"+Date.now()+"-"+crypto.randomBytes(3).toString("hex").toUpperCase(); }

async function handleIpaymuCreate(req, res) {
  try {
    // === ANTI DOUBLE ORDER: Idempotency Key ===
    const idemKey = req.headers['x-idempotency-key'] || req.body?.idempotencyKey || req.body?.idempotency_key;
    if(idemKey){
      const existing = checkIdempotency(idemKey);
      if(existing){
        console.log("IDEMPOTENCY HIT:", idemKey, "->", existing.invoice);
        return res.json({ success: true, duplicate: true, invoice: existing.invoice, message: "Transaksi sudah diproses sebelumnya (anti double click)", existing });
      }
    }

    if (!isConfigured(IPAYMU_VA) || !isConfigured(IPAYMU_API_KEY)) {
      return res.status(503).json({
        success: false,
        ok: false,
        message: "iPaymu belum dikonfigurasi di server.js"
      });
    }

    const {
      product,
      game,
      nominal,
      target,
      userId,
      zoneId,
      fields,
      contact,
      email,
      customerEmail,
      amount,
      total,
      invoice: clientInvoice,
      description,
      nickname,
      method
    } = req.body || {};

    const baseAmountRaw = amount ?? total;

    if (!baseAmountRaw || Number(baseAmountRaw) <= 0) {
      return res.status(400).json({
        success: false,
        ok: false,
        message: "Nominal pembayaran tidak valid"
      });
    }

    // === ITEM 9: tolak checkout untuk produk yang sudah tidak tersedia ===
    const availability = checkProductAvailability(game, product, { ...(fields || {}) });
    if (!availability.ok) {
      return res.status(409).json({
        success: false,
        ok: false,
        code: "PRODUCT_UNAVAILABLE",
        message: availability.message
      });
    }

    const control = checkoutControl();
    if (control.emergencyStop) {
      return res.status(503).json({ success:false, ok:false, code:"EMERGENCY_STOP", message:control.reason || "Checkout sedang dihentikan sementara oleh Dev." });
    }
    const maintenance = maintenanceMessage(game, product);
    if (maintenance) return res.status(503).json({ success:false, ok:false, code:"MAINTENANCE", message:maintenance });

    // === PROMO SERVER-SIDE: kode promo + flash sale + promo terjadwal ===
    const baseBeforePromo = Number(baseAmountRaw);
    const promoResult = getActiveDiscount({ game, product, promoCode: req.body?.promoCode || req.body?.promo || "", baseAmount: baseBeforePromo, userId: req.body?.userId || "" });
    if (promoResult.error) return res.status(400).json({ success:false, ok:false, code:"PROMO_INVALID", message:promoResult.error });
    const promoDiscount = Number(promoResult.discount || 0);
    const baseAmountAfterPromo = Math.max(1, baseBeforePromo - promoDiscount);

    // === STEP 1: Biaya layanan E-Wallet & QRIS 0.7% ===
    // Semua channel pembayaran di toko ini (DANA, GoPay, OVO, ShopeePay,
    // QRIS) diproses lewat iPaymu sebagai QRIS, jadi biaya 0.7% dikenakan
    // untuk semuanya. Dibulatkan ke atas per rupiah.
    const baseAmount = baseAmountAfterPromo;
    const serviceFeeAmount = calcPaymentServiceFee(baseAmount);
    const finalAmount = baseAmount + serviceFeeAmount;

    const PAYMENT_METHOD_LABELS = {
      dana: "DANA",
      gopay: "GoPay",
      ovo: "OVO",
      shopeepay: "ShopeePay",
      qris: "QRIS"
    };
    const normalizedMethod = String(method || "qris").toLowerCase();
    const paymentMethodLabel =
      PAYMENT_METHOD_LABELS[normalizedMethod] || "QRIS";

    // Pakai invoice yang sudah dibuat frontend (tapup.html) kalau ada,
    // supaya ID di frontend & backend sama dan polling status nyambung.
    const id = (clientInvoice && String(clientInvoice).trim()) || invoice();

    const order = {
      invoice: id,
      product: product || game || "Top Up",
      game: game || "",
      nominal: nominal || "",
      target: target || "",
      userId: userId || "",
      zoneId: zoneId || "",
      fields: fields || {},
      contact: contact || "",
      email: email || customerEmail || "",
      nickname: nickname || "",
      amount: Number(finalAmount),
      originalBaseAmount: baseBeforePromo,
      promoDiscount,
      promo: { code: String(req.body?.promoCode || req.body?.promo || "").trim().toUpperCase() || null, applied: promoResult.applied || [] },
      baseAmount,
      serviceFeeAmount,
      description: description || `Pembayaran ${product || game || "Top Up"}`,
      paymentMethod: paymentMethodLabel,
      paymentGateway: "IPAYMU",
      status: "WAITING_PAYMENT",
      paymentStatus: "PENDING",
      topupStatus: "WAITING",
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    // Simpan idempotency key segera setelah order dibuat (sebelum hit iPaymu)
    if(idemKey){ saveIdempotencyKey(idemKey, id, order.amount); }

    // iPaymu Direct Payment - selalu paymentMethod "qris" apapun
    // tombol yang dipilih customer (lihat catatan di atas).
    // name, phone, email, amount, paymentMethod wajib diisi.
    const relative = "/api/v2/payment/direct";
    const bodyObject = {
      product: [order.product],
      qty: [1],
      price: [order.amount],
      amount: order.amount,
      name: order.contact || "Pembeli",
      phone: order.contact || "08000000000",
      email: order.email || "customer@example.com",
      paymentMethod: "qris",
      notifyUrl: `${PUBLIC_URL}/api/payment/ipaymu/notify`,
      referenceId: id,
      comments: order.description,
      expired: 30,
      expiredType: "minutes"
    };

    const response = await axios.post(
      IPAYMU_BASE_URL + relative,
      bodyObject,
      {
        headers: iPaymuHeaders("POST", bodyObject),
        timeout: 30000
      }
    );

    order.ipaymuResponse = response.data;
    const data = response.data?.Data || response.data?.data || {};

    // Field resmi Data class iPaymu (Direct Payment): paymentNo, sessionId,
    // referenceId, transactionId, via, channel, paymentName, fee, total.
    // Untuk channel "qris", paymentNo BERISI konten QRIS yang harus digambar
    // jadi kode QR (iPaymu tidak mengirim gambar QR jadi, cuma string-nya).
    order.paymentCode = data?.paymentNo || data?.PaymentNo || "";

    order.ipaymuSessionId = data?.sessionId || data?.SessionID || "";
    order.ipaymuTransactionId = data?.transactionId || data?.TransactionId || "";
    order.ipaymuVia = data?.via || "";

    // checkoutUrl cuma terisi kalau akun/channel ini butuh redirect
    // (jarang untuk qris, tapi dicoba juga buat jaga-jaga).
    order.checkoutUrl =
      data?.url || data?.Url || data?.paymentUrl || data?.PaymentUrl || "";

    const rawQrImage = data?.qrImage || data?.QrImage || "";
    const rawQrContent =
      data?.qrString || data?.QrString ||
      data?.qrContent || data?.QrContent ||
      order.paymentCode ||
      order.checkoutUrl ||
      "";

    if (rawQrImage) {
      // iPaymu sudah kirim gambar QR (base64), pakai langsung.
      order.qrDataUrl = String(rawQrImage).startsWith("data:")
        ? rawQrImage
        : `data:image/png;base64,${rawQrImage}`;
    } else if (rawQrContent) {
      order.qrDataUrl = `https://api.qrserver.com/v1/create-qr-code/?size=320x320&data=${encodeURIComponent(rawQrContent)}`;
    } else {
      order.qrDataUrl = null;
    }

    order.expiresAt = Date.now() + 30 * 60 * 1000;

    orders[id] = order;
    saveOrders();

    res.json({
      success: true,
      ok: true,
      invoice: id,
      status: order.status,
      expiresAt: order.expiresAt,
      qrDataUrl: order.qrDataUrl,
      checkoutUrl: order.checkoutUrl || null,
      webRedirectUrl: order.checkoutUrl || null,
      paymentCode: order.paymentCode || null,
      paymentMethod: order.paymentMethod,
      order
    });
  } catch (error) {
    console.error(
      "IPAYMU CREATE:",
      error.response?.data || error.message
    );

    res.status(500).json({
      success: false,
      ok: false,
      message:
        (error.response?.data &&
          (error.response.data.Message ||
            error.response.data.message ||
            JSON.stringify(error.response.data))) ||
        error.message
    });
  }
}

