/* =========================================================
   EMAIL STRUK
========================================================= */

let mailer = null;

function getMailer() {
  if (!isConfigured(SMTP_USER) || !isConfigured(SMTP_PASS)) {
    throw new Error(
      "SMTP email belum dikonfigurasi di server.js"
    );
  }

  if (!mailer) {
    mailer = nodemailer.createTransport({
      host: SMTP_HOST,
      port: SMTP_PORT,
      secure: SMTP_SECURE,
      auth: {
        user: SMTP_USER,
        pass: SMTP_PASS
      }
    });
  }

  return mailer;
}

function escapeHtml(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function rupiah(value) {
  return new Intl.NumberFormat("id-ID", {
    style: "currency",
    currency: "IDR",
    maximumFractionDigits: 0
  }).format(Number(value || 0));
}

function receiptEmailHtml(order) {
  const date = new Date(order.createdAt || Date.now()).toLocaleDateString("id-ID", {
    day: "2-digit", month: "2-digit", year: "numeric"
  }).replaceAll("/", "-");
  const status = order.status === "SUCCESS" ? "BERHASIL" :
    ["FAILED", "TOPUP_FAILED"].includes(order.status) ? "GAGAL" :
    order.paymentStatus === "SUCCESS" ? "DIPROSES" : "MENUNGGU PEMBAYARAN";
  const values = [
    order.invoice || "-",
    order.target || order.userId || "-",
    [order.game, order.product, order.nominal].filter(Boolean).join(" - ") || "Top Up",
    new Intl.NumberFormat("id-ID", { maximumFractionDigits: 0 }).format(Number(order.amount || 0)),
    order.paymentMethod || "-",
    status,
    date
  ];
  const positions = [44.76, 48.47, 52.54, 56.61, 60.68, 64.87, 69.12];
  const valueLayers = values.map((value, i) => `
    <div style="position:absolute;left:53.1%;top:${positions[i]}%;width:23%;height:2.3%;display:flex;align-items:center;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-family:Georgia,'Times New Roman',serif;font-size:11px;line-height:1.1;font-weight:bold;color:#ebd296;text-transform:uppercase">${escapeHtml(value)}</div>
  `).join("");
  return `
<!doctype html>
<html lang="id">
<head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Struk TOPUP STORE</title></head>
<body style="margin:0;padding:16px;background:#05080d;font-family:Arial,sans-serif;text-align:center">
  <p style="margin:0 0 12px;color:#eef2f7;font-size:14px">Struk bukti pembayaran TOPUP STORE</p>
  <div role="img" aria-label="Struk bukti pembayaran TOPUP STORE" style="position:relative;width:100%;max-width:470px;height:auto;aspect-ratio:941/1671;margin:0 auto;background-image:url('data:image/jpeg;base64,');background-size:100% 100%;background-repeat:no-repeat;text-align:left">
    ${valueLayers}
  </div>
  <p style="margin:12px auto 0;max-width:470px;color:#b9c4d2;font-size:12px">Struk ini dibuat otomatis oleh sistem berdasarkan data transaksi.</p>
</body>
</html>`;
}

async function sendReceiptEmail(order) {
  const recipient = order.email || order.customerEmail;

  if (!recipient) {
    return {
      success: false,
      skipped: true,
      message: "Email pembeli tidak tersedia"
    };
  }

  if (order.receiptEmailSentAt) {
    return {
      success: true,
      skipped: true,
      message: "Struk sudah pernah dikirim"
    };
  }

  try {
    const transporter = getMailer();

    const info = await transporter.sendMail({
      from: MAIL_FROM,
      to: recipient,
      subject: `Struk TOPUP STORE - ${order.invoice}`,
      text:
        `Transaksi sukses\n` +
        `No. Transaksi: ${order.invoice}\n` +
        `Produk: ${order.product}\n` +
        `Nominal: ${order.nominal}\n` +
        `Target: ${order.target || order.userId || "-"}\n` +
        `Total: ${rupiah(order.amount)}`,
      html: receiptEmailHtml(order)
    });

    order.receiptEmailSentAt = new Date().toISOString();
    order.receiptEmailMessageId = info.messageId;
    order.receiptEmailError = null;
    saveOrders();

    console.log(
      `EMAIL STRUK TERKIRIM: ${recipient} / ${order.invoice}`
    );

    return {
      success: true,
      messageId: info.messageId
    };
  } catch (error) {
    order.receiptEmailError = error.message;
    saveOrders();

    console.error(
      "EMAIL STRUK GAGAL:",
      error.message
    );

    return {
      success: false,
      message: error.message
    };
  }
}

/* =========================================================
   CEK STATUS TRANSAKSI VIP SECARA BERKALA
========================================================= */

// FUNGSI INI SEBELUMNYA HILANG - dipanggil di fungsi cek status order tapi
// tidak pernah didefinisikan di file ini, jadi setiap kali polling status
// jalan (tiap 30 detik lewat processPendingVipOrders, atau saat customer
// buka /api/payment/ipaymu/status/:invoice) server akan CRASH dengan error
// "checkVipStatus is not defined". Ditambahkan di sini memakai endpoint
// resmi VIP Reseller: type "status" + trxid.
async function checkVipStatus(trxId) {
  return vipRequest({
    type: "status",
    trxid: String(trxId || "")
  });
}

async function refreshOrderStatus(order) {
  if (!order || !order.vipTrxId) return order;
  const provider = order.provider || "vip";

  if (provider === "vip" && !isConfigured(VIP_API_KEY)) return order;
  if ((provider === "melostore" || provider === "melo") && (!isConfigured(MELO_API_KEY) || !isConfigured(MELO_SECRET_KEY))) return order;

  try {
    const data = provider === "melostore" || provider === "melo"
      ? await checkMeloStatus(order.vipTrxId)
      : await checkVipStatus(order.vipTrxId);
    const status = provider === "melostore" || provider === "melo"
      ? meloResponseStatus(data)
      : vipResponseStatus(data);
    order.vipResponse = data;
    order.updatedAt = new Date().toISOString();

    if (status === "SUCCESS") {
      order.topupStatus = "SUCCESS";
      order.status = "SUCCESS";
      consumePromoCode(order);
      if (!order.emailResult?.success) {
        order.emailResult = await sendReceiptEmail(order);
      }
    } else if (status === "FAILED") {
      order.topupStatus = "FAILED";
      order.status = "TOPUP_FAILED";
    } else {
      order.topupStatus = "PROCESSING";
      order.status = "PROCESSING";
    }

    saveOrders();
  } catch (error) {
    console.error("VIP STATUS:", error.response?.data || error.message);
  }

  return order;
}

/* =========================================================
   FINALISASI: BAYAR SUKSES -> VIP -> EMAIL
========================================================= */

async function finishPaidOrder(order) {
  order.paymentStatus = "SUCCESS";
  order.status = "PAID";
  order.updatedAt = new Date().toISOString();

  if (order.topupStatus !== "SUCCESS") {
    const vip = await sendTopup(order);
    order.vipResponse = vip;
    order.vipTrxId = vip.trxId || extractVipTrxId(vip.data) || order.vipTrxId || "";

    if (vip.status === "SUCCESS") {
      order.topupStatus = "SUCCESS";
      order.status = "SUCCESS";
      order.updatedAt = new Date().toISOString();

      // Email hanya dikirim setelah top-up benar-benar sukses.
      order.emailResult = await sendReceiptEmail(order);
    } else if (vip.status === "FAILED") {
      order.topupStatus = "FAILED";
      order.status = "TOPUP_FAILED";
    } else {
      order.topupStatus = "PROCESSING";
      order.status = "PROCESSING";
    }
  }

  saveOrders();
  return order;
}

/* =========================================================
   WEBHOOK iPaymu
========================================================= */

app.post("/api/payment/ipaymu/notify", async (req, res) => {
  try {
    const data = req.body || {};

    const id =
      data.referenceId ||
      data.reference_id ||
      data.invoice ||
      data.ref_id ||
      data.transactionId;

    const order = orders[id];

    if (!order) {
      return res.json({
        success: true,
        message: "OK"
      });
    }

    const status = String(
      data.status ||
      data.transactionStatus ||
      data.result ||
      ""
    ).toUpperCase();

    order.ipaymuNotification = data;

    if (
      status === "SUCCESS" ||
      status === "SUKSES" ||
      status === "00"
    ) {
      await finishPaidOrder(order);
    } else if (
      status === "FAILED" ||
      status === "FAIL" ||
      status === "CANCELLED" ||
      status === "CANCELED"
    ) {
      order.paymentStatus = "FAILED";
      order.status = "FAILED";
      order.topupStatus = "NOT_STARTED";
      order.updatedAt = new Date().toISOString();
      saveOrders();
    } else {
      order.paymentStatus = "PENDING";
      order.status = "WAITING_PAYMENT";
      order.updatedAt = new Date().toISOString();
      saveOrders();
    }

    res.json({
      success: true,
      message: "OK"
    });
  } catch (error) {
    console.error(
      "IPAYMU NOTIFY:",
      error.response?.data || error.message
    );

    res.json({
      success: true,
      message: "OK"
    });
  }
});

/* =========================================================
   STATUS iPaymu
========================================================= */

async function handleIpaymuStatus(req, res) {
  const id = decodeURIComponent(req.params.invoice);
  const order = orders[id];

  if (!order) {
    return res.status(404).json({
      ok: false,
      success: false,
      message: "Transaksi tidak ditemukan"
    });
  }

  if (
    order.paymentStatus === "SUCCESS" &&
    order.topupStatus === "PROCESSING" &&
    order.vipTrxId
  ) {
    await refreshOrderStatus(order);
  }

  let frontendStatus = null;
  if (order.status === "SUCCESS") frontendStatus = "SUKSES";
  else if (["FAILED", "TOPUP_FAILED"].includes(order.status)) frontendStatus = "GAGAL";
  else if (["PAID", "PROCESSING"].includes(order.status)) frontendStatus = "DIPROSES";

  const frontendPaymentStatus =
    order.paymentStatus === "SUCCESS" ? "PAID" : order.paymentStatus;

  res.json({
    ok: true,
    success: true,
    invoice: order.invoice,
    status: frontendStatus,
    paymentStatus: frontendPaymentStatus,
    topupStatus: order.topupStatus,
    vipStatus: order.topupStatus,
    vipTrxId:
      order.vipResponse?.data?.data?.trxid ||
      order.vipResponse?.data?.trxid ||
      null,
    note:
      order.vipResponse?.message ||
      order.vipResponse?.data?.message ||
      null,
    emailReceiptSent: order.emailResult?.success === true,
    emailReceiptError:
      order.emailResult && order.emailResult.success === false
        ? order.emailResult.message || "Gagal mengirim email struk"
        : null,
    order
  });
}

app.get("/api/payment/ipaymu/status/:invoice", handleIpaymuStatus);
app.get("/api/payment/dana/status/:invoice", handleIpaymuStatus);

