const RECEIPT_PAGE_HTML = "<!DOCTYPE html>\n<html lang=\"id\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Bukti Pembayaran</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@700&family=Poppins:wght@400;500;600&display=swap\" rel=\"stylesheet\">\n<style>\n  :root { --gold: #f0d9a6; }\n  * { box-sizing: border-box; }\n  html, body {\n    margin: 0;\n    height: 100%;\n    background: #05080d;\n    overflow: hidden;\n  }\n  body {\n    color: #eef2f7;\n    font-family: 'Poppins', -apple-system, sans-serif;\n    display: flex;\n  }\n  .preview-wrap {\n    width: 100vw;\n    height: 100dvh;\n  }\n  canvas {\n    display: block;\n    width: 100vw;\n    height: 100dvh;\n    object-fit: cover;\n    background: #000;\n  }\n  button {\n    margin-top: 18px;\n    width: 100%;\n    max-width: 380px;\n    padding: 13px 14px;\n    border-radius: 9px;\n    border: none;\n    font-family: 'Poppins', sans-serif;\n    font-weight: 600;\n    font-size: 14px;\n    cursor: pointer;\n    background: linear-gradient(135deg, #f3d99a, #c9973f);\n    color: #26190a;\n    transition: transform 0.12s;\n  }\n  button:active { transform: scale(0.97); }\n  #status-msg {\n    margin-top: 10px;\n    font-size: 12.5px;\n    min-height: 16px;\n    color: #8fb3d9;\n    text-align: center;\n  }\n</style>\n</head>\n<body>\n\n<div class=\"preview-wrap\">\n  <canvas id=\"canvas\" width=\"941\" height=\"1671\"></canvas>\n</div>\n\n<script>\n/* =====================================================================\n   UBAH DATA DI BAWAH INI SESUAI TRANSAKSI, LALU SIMPAN FILE & REFRESH\n   ===================================================================== */\nconst DATA = {\n  idTransaksi: \"\",\n  idPlayer: \"\",\n  produk: \"\",\n  harga: \"\",\n  metode: \"\",\n  status: \"\",\n  tanggal: \"\",\n};\n\n// Ambil data transaksi dari server menggunakan invoice pada URL.\nasync function loadReceiptData() {\n  const invoiceId = new URLSearchParams(window.location.search).get(\"invoice\");\n  if (!invoiceId) return;\n  try {\n    const response = await fetch(`/api/receipt/${encodeURIComponent(invoiceId)}`);\n    const result = await response.json();\n    if (!response.ok || !result.success || !result.order) return;\n    const order = result.order;\n    const date = new Date(order.createdAt || Date.now());\n    DATA.idTransaksi = order.invoice || invoiceId;\n    DATA.idPlayer = order.target || order.userId || \"-\";\n    DATA.produk = [order.game, order.product, order.nominal].filter(Boolean).join(\" - \") || \"Top Up\";\n    DATA.harga = String(Number(order.amount || 0).toLocaleString(\"id-ID\"));\n    DATA.metode = order.paymentMethod || \"-\";\n    DATA.status = order.status === \"SUCCESS\" ? \"BERHASIL\" :\n      [\"TOPUP_FAILED\", \"FAILED\"].includes(order.status) ? \"GAGAL\" :\n      order.paymentStatus === \"SUCCESS\" ? \"DIPROSES\" : \"MENUNGGU PEMBAYARAN\";\n    DATA.tanggal = date.toLocaleDateString(\"id-ID\", {\n      day: \"2-digit\", month: \"2-digit\", year: \"numeric\"\n    }).replaceAll(\"/\", \"-\");\n    render();\n  } catch (error) {\n    console.error(\"Gagal memuat data struk\", error);\n  }\n}\n/* ===================================================================== */\n\nconst bgImage = new Image();\nbgImage.src = \"data:image/jpeg;base64,\";\n\nconst canvas = document.getElementById('canvas');\nconst ctx = canvas.getContext('2d');\n\nconst FIELD_Y = { idTransaksi: 748, idPlayer: 811, produk: 878, harga: 946, metode: 1014, status: 1084, tanggal: 1155 };\nconst VALUE_X = 500;\nconst MAX_RIGHT = 716;\nconst MAX_WIDTH = MAX_RIGHT - VALUE_X;\nconst GOLD = \"#ebd296\";\n\nfunction fittedFont(text, maxWidth, maxSize) {\n  let size = maxSize;\n  ctx.font = `700 ${size}px Cinzel, serif`;\n  while (ctx.measureText(text).width > maxWidth && size > 12) {\n    size -= 1;\n    ctx.font = `700 ${size}px Cinzel, serif`;\n  }\n  return size;\n}\n\nfunction drawValue(text, y) {\n  const upper = String(text).toUpperCase();\n  const size = fittedFont(upper, MAX_WIDTH, 22);\n  ctx.font = `700 ${size}px Cinzel, serif`;\n  ctx.fillStyle = GOLD;\n  ctx.textBaseline = 'middle';\n  ctx.textAlign = 'left';\n  ctx.fillText(upper, VALUE_X, y);\n}\n\nfunction render() {\n  ctx.clearRect(0, 0, canvas.width, canvas.height);\n  ctx.drawImage(bgImage, 0, 0, canvas.width, canvas.height);\n  drawValue(DATA.idTransaksi, FIELD_Y.idTransaksi);\n  drawValue(DATA.idPlayer,    FIELD_Y.idPlayer);\n  drawValue(DATA.produk,      FIELD_Y.produk);\n  drawValue(DATA.harga,       FIELD_Y.harga);\n  drawValue(DATA.metode,      FIELD_Y.metode);\n  drawValue(DATA.status,      FIELD_Y.status);\n  drawValue(DATA.tanggal,     FIELD_Y.tanggal);\n}\n\nif (document.fonts && document.fonts.ready) {\n  document.fonts.load('700 22px Cinzel').then(render);\n  document.fonts.ready.then(render);\n}\nbgImage.onload = render;\nloadReceiptData();\n\n/* Area tombol \"DOWNLOAD\" pada gambar (koordinat asli 941x1671) */\nconst DL_BTN = { x1: 300, y1: 1340, x2: 645, y2: 1445 };\n\nlet downloadsNS = null;\n(async () => {\n  try { downloadsNS = await claude.use('downloads'); } catch (e) { downloadsNS = null; }\n})();\n\nfunction triggerDownload() {\n  canvas.toBlob(async (blob) => {\n    if (!blob) return;\n    const filename = `bukti-${(DATA.idTransaksi || 'pembayaran').replace(/[^a-zA-Z0-9_-]/g,'')}.jpg`;\n    try {\n      if (downloadsNS) {\n        await downloadsNS.save({ filename, data: blob });\n      } else {\n        const url = URL.createObjectURL(blob);\n        const a = document.createElement('a');\n        a.href = url; a.download = filename;\n        document.body.appendChild(a); a.click(); a.remove();\n        setTimeout(() => URL.revokeObjectURL(url), 4000);\n      }\n    } catch (err) { /* diam saja kalau dibatalkan */ }\n  }, 'image/jpeg', 0.92);\n}\n\nfunction isInDownloadBtn(clientX, clientY) {\n  const rect = canvas.getBoundingClientRect();\n  const nativeW = canvas.width, nativeH = canvas.height;\n  const scale = Math.max(rect.width / nativeW, rect.height / nativeH); // object-fit: cover\n  const scaledW = nativeW * scale, scaledH = nativeH * scale;\n  const offsetX = (rect.width - scaledW) / 2;\n  const offsetY = (rect.height - scaledH) / 2;\n  const x = (clientX - rect.left - offsetX) / scale;\n  const y = (clientY - rect.top - offsetY) / scale;\n  return x >= DL_BTN.x1 && x <= DL_BTN.x2 && y >= DL_BTN.y1 && y <= DL_BTN.y2;\n}\n\ncanvas.style.cursor = 'pointer';\ncanvas.addEventListener('click', (e) => {\n  if (isInDownloadBtn(e.clientX, e.clientY)) triggerDownload();\n});\n</script>\n</body>\n</html>\n";

