/* =========================================================
   ITEM 12 - KELOLA KATALOG DARI DEV (tanpa edit HTML)
   Produk : aktif/nonaktif, harga jual, nama tampilan, urutan, catatan
   Game   : sembunyikan, urutan, pindah kategori
   Disimpan di vip-catalog.json / melo-catalog.json / vip-catalog-meta.json.
========================================================= */
const CATALOG_CATEGORIES = ["gamesOnline", "apps", "pulsa", "kuota", "tv", "pln", "wallets"];

app.post("/api/dev/catalog/game", (req, res) => {
  if (!requireDevAuth(req, res)) return;
  const name = String(req.body?.name || "").trim();
  if (!name) return res.status(400).json({ success: false, message: "Nama game wajib diisi." });
  const category = String(req.body?.category || "").trim();
  if (category && !CATALOG_CATEGORIES.includes(category)) {
    return res.status(400).json({ success: false, message: "Kategori tidak dikenal." });
  }
  const sortOrder = Math.max(0, Math.round(Number(req.body?.sortOrder) || 0));
  const hidden = req.body?.hidden === true || req.body?.hidden === "true";

  vipCatalogMeta.gameSettings = vipCatalogMeta.gameSettings || {};
  const key = normalizeText(name);
  if (!hidden && !sortOrder && !category) {
    delete vipCatalogMeta.gameSettings[key];   // semua kembali default
  } else {
    vipCatalogMeta.gameSettings[key] = { name, hidden, sortOrder, category };
  }
  saveVipCatalogMeta();
  res.json({ success: true, setting: vipCatalogMeta.gameSettings[key] || null });
});

app.post("/api/dev/catalog/product", (req, res) => {
  if (!requireDevAuth(req, res)) return;
  const provider = String(req.body?.provider || "vip").toLowerCase();
  const isMelo = provider === "melostore" || provider === "melo";
  const catalog = isMelo ? meloCatalog : vipCatalog;
  const code = String(req.body?.code || "").trim();
  const item = catalog[code];
  if (!item) return res.status(404).json({ success: false, message: "Kode produk tidak ditemukan di katalog aktif." });

  const b = req.body || {};
  if (b.enabled !== undefined) item.enabled = !(b.enabled === false || b.enabled === "false");
  if (b.displayName !== undefined) item.displayName = String(b.displayName).trim().slice(0, 80);
  if (b.note !== undefined) item.note = String(b.note).trim().slice(0, 160);
  if (b.sortOrder !== undefined) item.sortOrder = Math.max(0, Math.round(Number(b.sortOrder) || 0));

  const cost = Number(isMelo ? item.meloPrice : item.vipPrice);
  let warning = null;
  if (b.resetPrice === true || b.resetPrice === "true") {
    item.sellingPrice = cost;
    item.priceOverridden = false;
  } else if (b.sellingPrice !== undefined && b.sellingPrice !== "") {
    const price = Math.round(Number(b.sellingPrice));
    if (!(price > 0)) return res.status(400).json({ success: false, message: "Harga jual harus lebih dari 0." });
    item.sellingPrice = price;
    item.priceOverridden = true;
    if (price < cost) warning = `Harga jual (${price}) di bawah harga modal (${cost}). Setiap penjualan akan rugi.`;
  }
  item.updatedAt = new Date().toISOString();
  if (isMelo) saveMeloCatalog(); else saveVipCatalog();

  res.json({
    success: true,
    warning,
    product: isMelo ? normalizeMeloCatalogItem(item) : normalizeVipCatalogItem(item)
  });
});

/* =========================================================
   ITEM 10 - LAPORAN PENJUALAN & KEUNTUNGAN (khusus Dev)
   Dihitung dari transaksi yang benar-benar tercatat di orders.json.
   - omzet   = nominal produk (tanpa fee) dari order yang top up-nya SUKSES dan tidak di-refund
   - modal   = harga modal provider yang dicatat saat top up dikirim
   - untung  = omzet - modal (- modal order yang sudah sukses tapi di-refund)
   - fee     = biaya layanan 0,7% dari pembeli (bukan untung; diteruskan ke biaya payment gateway)
========================================================= */
// PERBAIKAN: dulu ada requireDevAuth versi kedua di sini yang mengecek
// devId+devPass ke akun user ber-flag isDev. Frontend TIDAK PERNAH mengirim
// devId/devPass (selalu devToken+devPassword), jadi versi ini bikin semua
// endpoint dev (promo, maintenance, flash sale, backup, checkout control,
// dashboard, refund, dll) selalu ditolak walau password benar. Sudah dihapus;
// requireDevAuth yang dipakai sekarang cuma satu, didefinisikan di atas
// (dekat verifyDevSession/isValidDevPassword), sesuai yang dikirim frontend.

function wibDay(ms) {
  return new Date(ms + 7 * 3600 * 1000).toISOString().slice(0, 10);
}

function orderCostInfo(order) {
  const recorded = Number(order.costPrice);
  if (recorded > 0) return { cost: recorded, source: "recorded" };
  const { isMelo, code } = resolveCatalogCode(order.game, order.product, order.fields || {}, order.provider, order.serviceCode);
  const item = (isMelo ? meloCatalog : vipCatalog)[code];
  const est = Number(isMelo ? item?.meloPrice : item?.vipPrice);
  if (est > 0) return { cost: est, source: "estimated" };
  return { cost: 0, source: "unknown" };
}

function buildSalesReport(fromStr, toStr) {
  const fromMs = fromStr ? Date.parse(`${fromStr}T00:00:00+07:00`) : -Infinity;
  const toMs = toStr ? Date.parse(`${toStr}T23:59:59.999+07:00`) : Infinity;

  const r = {
    totalOrders: 0, waitingPayment: 0, paidOrders: 0, successOrders: 0,
    processingOrders: 0, topupFailedOrders: 0, refundedOrders: 0,
    revenue: 0, providerCost: 0, feeCollected: 0, refundTotal: 0,
    lostCostFromRefund: 0, profit: 0,
    estimatedCostOrders: 0, unknownCostOrders: 0, unknownCostRevenue: 0
  };
  const byProvider = {};
  const byDay = {};
  const byProduct = {};
  const bump = (map, key) => (map[key] = map[key] || { orders: 0, revenue: 0, cost: 0, profit: 0 });

  for (const order of Object.values(orders)) {
    const t = Date.parse(order.createdAt || "");
    if (!Number.isFinite(t) || t < fromMs || t > toMs) continue;
    r.totalOrders++;

    const paid = order.paymentStatus === "SUCCESS";
    const refunded = order.refundStatus === "REFUNDED";
    if (!paid) { r.waitingPayment++; continue; }
    r.paidOrders++;

    if (refunded) {
      r.refundedOrders++;
      r.refundTotal += Number(order.refundAmount || 0);
      if (order.topupStatus === "SUCCESS") {
        const { cost } = orderCostInfo(order);
        r.lostCostFromRefund += cost;
      }
      continue;
    }
    if (order.topupStatus === "FAILED" || order.status === "TOPUP_FAILED") { r.topupFailedOrders++; continue; }
    if (order.topupStatus !== "SUCCESS") { r.processingOrders++; continue; }

    r.successOrders++;
    const revenue = Number(order.baseAmount || 0);
    const { cost, source } = orderCostInfo(order);
    r.feeCollected += Number(order.serviceFeeAmount || 0);
    if (source === "unknown") {
      r.unknownCostOrders++;
      r.unknownCostRevenue += revenue;
      continue; // untung tidak dihitung tanpa modal yang jelas
    }
    if (source === "estimated") r.estimatedCostOrders++;

    const profit = revenue - cost;
    r.revenue += revenue;
    r.providerCost += cost;

    const prov = order.costProvider || order.provider || "vip";
    const day = wibDay(t);
    const prod = order.product || order.game || "Lainnya";
    for (const [map, key] of [[byProvider, prov], [byDay, day], [byProduct, prod]]) {
      const b = bump(map, key);
      b.orders++; b.revenue += revenue; b.cost += cost; b.profit += profit;
    }
  }
  r.profit = r.revenue - r.providerCost - r.lostCostFromRefund;

  return {
    range: { from: fromStr || null, to: toStr || null, timezone: "WIB (UTC+7)" },
    summary: r,
    byProvider,
    byDay: Object.entries(byDay).sort((a, b) => (a[0] < b[0] ? 1 : -1)).slice(0, 31).map(([date, v]) => ({ date, ...v })),
    topProducts: Object.entries(byProduct).sort((a, b) => b[1].profit - a[1].profit).slice(0, 5).map(([name, v]) => ({ name, ...v }))
  };
}

app.get("/api/dev/dashboard", (req,res)=>{ if(!requireDevAuth(req,res))return; res.json({success:true,...buildDevDashboard()}); });

app.post("/api/dev/report", (req, res) => {
  if (!requireDevAuth(req, res)) return;
  const dateOk = v => !v || /^\d{4}-\d{2}-\d{2}$/.test(String(v));
  const from = String(req.body?.from || "").trim();
  const to = String(req.body?.to || "").trim();
  if (!dateOk(from) || !dateOk(to)) {
    return res.status(400).json({ success: false, message: "Format tanggal harus YYYY-MM-DD." });
  }
  res.json({ success: true, ...buildSalesReport(from, to) });
});

// Mencatat refund di order. Ini HANYA pencatatan: pengembalian dana ke pembeli
// tetap dilakukan manual lewat dashboard iPaymu.
app.post("/api/dev/order/refund", (req, res) => {
  if (!requireDevAuth(req, res)) return;
  const inv = String(req.body?.invoice || "").trim();
  const order = orders[inv];
  if (!order) return res.status(404).json({ success: false, message: "Invoice tidak ditemukan." });
  if (order.paymentStatus !== "SUCCESS") {
    return res.status(400).json({ success: false, message: "Order ini belum dibayar, tidak ada yang bisa di-refund." });
  }
  if (order.refundStatus === "REFUNDED") {
    return res.status(400).json({ success: false, message: "Order ini sudah dicatat refund." });
  }
  const amount = req.body?.amount === undefined || req.body?.amount === "" ? Number(order.amount) : Number(req.body.amount);
  if (!(amount > 0) || amount > Number(order.amount)) {
    return res.status(400).json({ success: false, message: `Nominal refund harus antara 1 dan ${Number(order.amount)}.` });
  }
  order.refundStatus = "REFUNDED";
  order.refundAmount = amount;
  order.refundedAt = new Date().toISOString();
  order.refundNote = String(req.body?.note || "").slice(0, 200);
  order.updatedAt = new Date().toISOString();
  saveOrders();
  res.json({ success: true, invoice: inv, refundAmount: amount, refundedAt: order.refundedAt });
});

