// ===== FIXED: BANTUAN DENGAN SCREENSHOT - KIRIM EMAIL VIA BACKEND (FIX MAILTO ATTACH BUG) =====
app.post("/api/help/send", async (req, res)=>{
  try{
    const { name, email, category, message, userId, evidence, subject } = req.body||{};
    const now = new Date().toISOString();
    
    // Simpan ke dev-log / feedback file
    try{
      const feedbackFile = path.join(DATA_DIR, "feedbacks.json");
      let feedbacks = [];
      try{ feedbacks = JSON.parse(fs.readFileSync(feedbackFile,"utf8")||"[]"); }catch(e){ feedbacks=[]; }
      const id = "HELP-"+Date.now();
      const entry = {
        id,
        name: name||"Pelapor",
        email: email||"",
        category: category||"bantuan_screenshot",
        message: message||"",
        userId: userId||"",
        hasEvidence: !!evidence,
        evidenceName: evidence?.name||"",
        createdAt: now,
        ip: req.ip
      };
      feedbacks.push(entry);
      fs.writeFileSync(feedbackFile, JSON.stringify(feedbacks, null, 2));
      logDevAction("help_with_screenshot", req.ip, { id, email, hasEvidence: !!evidence });
    }catch(e){ console.log("save feedback error", e.message); }

    // Kirim email via nodemailer jika SMTP configured (sudah ada di server.js)
    try{
      if(SMTP_USER && SMTP_PASS){
        const transporter = nodemailer.createTransport({
          host: SMTP_HOST,
          port: SMTP_PORT,
          secure: SMTP_SECURE,
          auth: { user: SMTP_USER, pass: SMTP_PASS }
        });

        const mailOptions = {
          from: MAIL_FROM,
          to: "topupstore100@gmail.com",
          subject: subject || "Bantuan TOPUP STORE⚡ + Screenshot Bukti",
          text: `Dari: ${name||"-"} (${email||"-"})\nUserID: ${userId||"-"}\nWaktu: ${now}\nIP: ${req.ip}\n\n${message||"-"}\n\n---\nKategori: ${category||"-"}`,
          html: `<div style="font-family:sans-serif;padding:16px;background:#f9f9f9;border-radius:8px;">
            <h3 style="color:#f59e0b;">Bantuan TOPUP STORE⚡ + Screenshot</h3>
            <p><b>Nama:</b> ${name||"-"}<br><b>Email:</b> ${email||"-"}<br><b>UserID:</b> ${userId||"-"}<br><b>Waktu:</b> ${now}<br><b>IP:</b> ${req.ip}</p>
            <div style="background:#fff;padding:12px;border-radius:8px;border:1px solid #ddd;white-space:pre-wrap;">${(message||"").replace(/</g,"&lt;")}</div>
            <p style="font-size:12px;color:#666;">Kategori: ${category||"-"}</p>
          </div>`
        };

        if(evidence && evidence.data){
          // evidence.data is base64 dataURL
          const base64 = String(evidence.data).split(",")[1] || evidence.data;
          mailOptions.attachments = [{
            filename: evidence.name || "screenshot.jpg",
            content: base64,
            encoding: "base64"
          }];
        }

        const info = await transporter.sendMail(mailOptions);
        console.log("help email sent", info.messageId);
        return res.json({ success:true, id:"HELP-"+Date.now(), messageId: info.messageId, note:"Email + screenshot terkirim ke CS" });
      }
    }catch(mailErr){
      console.log("help mail error", mailErr.message);
      // tetap return success karena sudah disimpan ke feedbacks.json
      return res.json({ success:true, id:"HELP-"+Date.now(), warning:"Saved but email failed: "+mailErr.message });
    }

    return res.json({ success:true, id:"HELP-"+Date.now(), note:"Bantuan tersimpan, email akan diproses" });
  }catch(e){
    console.error("help/send error", e);
    res.status(500).json({ success:false, message:e.message });
  }
});

app.post("/api/refund/request", async (req,res)=>{
  const invoiceId=String(req.body?.invoice||req.body?.orderId||"").trim(); const order=orders[invoiceId];
  if(!order) return res.status(404).json({success:false,message:"Order tidak ditemukan."});
  if(order.paymentStatus!=="SUCCESS") return res.status(400).json({success:false,message:"Refund hanya bisa diajukan untuk order yang sudah dibayar."});
  if(order.refundStatus || order.refundRequestId) return res.status(409).json({success:false,message:"Order ini sudah memiliki proses refund."});
  const reason=String(req.body?.reason||"").trim(); if(reason.length<5) return res.status(400).json({success:false,message:"Alasan refund minimal 5 karakter."});
  const rawEvidence=req.body?.evidence;
  let evidence=null;
  if(rawEvidence && typeof rawEvidence === "object") {
    const data=String(rawEvidence.data||"");
    const type=String(rawEvidence.type||"");
    const name=String(rawEvidence.name||"bukti-refund").slice(0,120);
    if(!type.startsWith("image/") || !/^data:image\/(png|jpe?g|webp|gif);base64,/i.test(data)) return res.status(400).json({success:false,message:"Bukti refund harus berupa gambar."});
    if(data.length>2600000) return res.status(413).json({success:false,message:"Ukuran foto bukti terlalu besar."});
    evidence={name,type,data,uploadedAt:new Date().toISOString()};
  }
  if(!evidence) return res.status(400).json({success:false,message:"Bukti transfer / screenshot riwayat order wajib dilampirkan."});
  const db=refundDb(), id=refundRequestId(); const item={id,invoice:invoiceId,userId:order.userId||"",email:String(req.body?.email||order.email||"").trim(),reason:reason.slice(0,500),amount:Number(order.amount||0),evidence,status:"PENDING",createdAt:new Date().toISOString(),updatedAt:new Date().toISOString()};
  db.requests[id]=item; saveRefundDb(db); order.refundRequestId=id; order.refundStatus="PENDING"; order.updatedAt=new Date().toISOString(); saveOrders();
  await sendDevEmail(`Refund baru ${id} - ${invoiceId}`,`<p>Refund baru masuk.</p><p>ID: <b>${escapeHtml(id)}</b><br>Invoice: <b>${escapeHtml(invoiceId)}</b><br>Nominal: <b>${rupiah(item.amount)}</b><br>Alasan: ${escapeHtml(item.reason)}<br>Bukti: ${evidence ? escapeHtml(evidence.name) : "-"}</p>`);
  res.json({success:true,request:item});
});
