app.post("/api/dev/refunds/:id",async(req,res)=>{ if(!requireDevAuth(req,res))return; const db=refundDb(), r=db.requests[req.params.id]; if(!r)return res.status(404).json({success:false,message:"Refund tidak ditemukan"}); const action=String(req.body?.action||"").toUpperCase(); if(!["PROCESS","APPROVE","REJECT"].includes(action))return res.status(400).json({success:false,message:"Action harus PROCESS, APPROVE atau REJECT"}); const order=orders[r.invoice]; if(!order)return res.status(404).json({success:false,message:"Order refund tidak ditemukan"}); if(action==="PROCESS"){ r.status="DIPROSES"; r.adminNote=String(req.body?.note||"").slice(0,500); r.updatedAt=new Date().toISOString(); saveRefundDb(db); order.refundStatus="DIPROSES"; order.refundNote=r.adminNote; order.updatedAt=r.updatedAt; saveOrders(); return res.json({success:true,request:r}); } const oldStatus=r.status; r.status=action==="APPROVE"?"APPROVED":"REJECTED"; r.adminNote=String(req.body?.note||"").slice(0,500); r.updatedAt=new Date().toISOString(); r.processedAt=r.updatedAt; if(action==="APPROVE"){ const amount=Number(r.amount||order.refundAmount||order.amount||0); if(!(amount>0)||amount>Number(order.amount||0)) return res.status(400).json({success:false,message:"Nominal refund tidak valid"}); r.amount=amount; if(order.userId && (order.paymentMethod==="SALDO" || order.paidWithBalance===true)){ const data=getDeposits(); data.balances[order.userId]=Number(data.balances[order.userId]||0)+amount; const id="REFUND-"+Date.now(); data.deposits[id]={id,userId:order.userId,amount,type:"refund",invoice:order.invoice,status:"SUCCESS",createdAt:r.updatedAt,balanceAfter:data.balances[order.userId]}; saveDeposits(data); r.balanceReturned=true; r.balanceReturnedAt=r.updatedAt; } } saveRefundDb(db); order.refundStatus=r.status; order.refundAmount=r.amount; order.refundProcessedAt=r.processedAt; order.refundNote=r.adminNote; order.updatedAt=r.updatedAt; saveOrders(); if(r.email){try{await getMailer().sendMail({from:MAIL_FROM,to:r.email,subject:`Status refund ${r.invoice} - ${r.status}`,html:`<p>Pengajuan refund <b>${escapeHtml(r.id)}</b> untuk <b>${escapeHtml(r.invoice)}</b> sekarang <b>${escapeHtml(r.status)}</b>.</p><p>${escapeHtml(r.adminNote||"")}</p>`});}catch(e){}} res.json({success:true,request:r,previousStatus:oldStatus}); });
