// API data struk: hanya mengembalikan kolom yang dibutuhkan, bukan seluruh order.
app.get("/api/receipt/:invoice", (req, res) => {
  const id = decodeURIComponent(req.params.invoice);
  const order = orders[id];
  if (!order) {
    return res.status(404).json({ success: false, message: "Transaksi tidak ditemukan" });
  }
  const status = order.status === "SUCCESS" ? "SUCCESS" :
    ["FAILED", "TOPUP_FAILED"].includes(order.status) ? order.status :
    order.paymentStatus === "SUCCESS" ? "PROCESSING" : "WAITING_PAYMENT";
  res.json({
    success: true,
    order: {
      invoice: order.invoice,
      target: order.target || order.userId || "",
      game: order.game || "",
      product: order.product || "",
      nominal: order.nominal || "",
      amount: Number(order.amount || 0),
      paymentMethod: order.paymentMethod || "-",
      status,
      paymentStatus: order.paymentStatus || "PENDING",
      createdAt: order.createdAt || null
    }
  });
});

app.get("/api/order/:invoice", (req, res) => {
  const id = decodeURIComponent(req.params.invoice);
  const order = orders[id];

  if (!order) {
    return res.status(404).json({
      success: false,
      message: "Transaksi tidak ditemukan"
    });
  }

  res.json({
    success: true,
    order
  });
});

app.post("/api/topup/retry/:invoice", async (req, res) => {
  const id = decodeURIComponent(req.params.invoice);
  const order = orders[id];

  if (!order) {
    return res.status(404).json({
      success: false,
      message: "Transaksi tidak ditemukan"
    });
  }

  if (
    order.paymentStatus !== "SUCCESS" &&
    order.status !== "PAID" &&
    order.status !== "PROCESSING"
  ) {
    return res.status(400).json({
      success: false,
      message: "Pembayaran belum berhasil"
    });
  }

  const vip = await sendTopup(order);

  order.vipResponse = vip;
  order.vipTrxId = vip.trxId || extractVipTrxId(vip.data) || order.vipTrxId || "";
  order.topupStatus =
    vip.status === "SUCCESS"
      ? "SUCCESS"
      : vip.status === "FAILED"
        ? "FAILED"
        : "PROCESSING";

  order.status =
    vip.status === "SUCCESS"
      ? "SUCCESS"
      : vip.status === "FAILED"
        ? "TOPUP_FAILED"
        : "PROCESSING";

  order.updatedAt = new Date().toISOString();

  if (vip.status === "SUCCESS") {
    order.emailResult = await sendReceiptEmail(order);
  }

  saveOrders();

  res.json({
    success: true,
    invoice: id,
    status: order.status,
    topupStatus: order.topupStatus,
    result: vip
  });
});

app.post("/api/receipt/resend/:invoice", async (req, res) => {
  const id = decodeURIComponent(req.params.invoice);
  const order = orders[id];

  if (!order) {
    return res.status(404).json({
      success: false,
      message: "Transaksi tidak ditemukan"
    });
  }

  if (order.status !== "SUCCESS" || order.topupStatus !== "SUCCESS") {
    return res.status(400).json({
      success: false,
      message: "Struk hanya dapat dikirim setelah top-up sukses"
    });
  }

  // Reset flag agar bisa dikirim ulang.
  order.receiptEmailSentAt = null;
  order.receiptEmailMessageId = null;

  const result = await sendReceiptEmail(order);

  res.json({
    success: result.success,
    invoice: id,
    result
  });
});

// Dipanggil tapup.html (sendReceiptEmailAfterSuccess) setelah status jadi
// SUKSES di sisi frontend. Prioritas pakai data order yang tersimpan di
// server (lebih bisa dipercaya); kalau invoice-nya belum ada di server,
// baru pakai data yang dikirim frontend sebagai cadangan.
app.post("/api/email/receipt", async (req, res) => {
  try {
    const { email, order: incoming } = req.body || {};
    const invoiceId = incoming?.invoice || incoming?.trxId || "";
    const existing = orders[invoiceId];

    const mailOrder = existing || {
      invoice: invoiceId,
      product: incoming?.item || incoming?.product || "Top Up",
      game: incoming?.game || incoming?.item || "",
      nominal: incoming?.nominal || "",
      target: incoming?.target || "",
      nickname: incoming?.nickname || "",
      paymentMethod: incoming?.method || incoming?.paymentMethod || "-",
      amount: Number(incoming?.total ?? incoming?.rawPrice ?? incoming?.amount ?? 0),
      email: email || incoming?.email || "",
      createdAt: incoming?.createdAt || new Date().toISOString(),
      updatedAt: incoming?.createdAt || new Date().toISOString(),
      receiptEmailSentAt: null
    };

    if (email) mailOrder.email = email;

    if (!mailOrder.email) {
      return res.status(400).json({
        ok: false,
        success: false,
        message: "Email tujuan tidak ada"
      });
    }

    const result = await sendReceiptEmail(mailOrder);

    res.json({
      ok: result.success,
      success: result.success,
      message: result.message || null
    });
  } catch (error) {
    console.error("EMAIL RECEIPT:", error.response?.data || error.message);
    res.status(500).json({
      ok: false,
      success: false,
      message: error.message || "Gagal mengirim email struk"
    });
  }
});

/* =========================================================
   PRODUK / HARGA VIP
========================================================= */

function normalizeProductList(data) {
  if (Array.isArray(data)) return data;

  if (Array.isArray(data?.data)) return data.data;
  if (Array.isArray(data?.products)) return data.products;
  if (Array.isArray(data?.result)) return data.result;

  if (data?.data && typeof data.data === "object") {
    return Object.values(data.data);
  }

  if (data && typeof data === "object") {
    const values = Object.values(data);
    if (values.some(v => v && typeof v === "object")) {
      return values;
    }
  }

  return [];
}

function productKey(item) {
  return String(
    item?.code ||
    item?.sku ||
    item?.product_code ||
    item?.productCode ||
    item?.id ||
    item?.name ||
    ""
  ).trim();
}

function priceOf(item) {
  return Number(
    item?.price ??
    item?.harga ??
    item?.selling_price ??
    item?.sellingPrice ??
    item?.price_sell ??
    0
  );
}

async function syncPrices() {
  if (!isConfigured(VIP_API_URL)) return;

  // Endpoint produk dapat berbeda di provider VIP.
  // Isi URL produk yang benar bila provider lu menyediakan endpoint khusus.
  const productsUrl = process.env.VIP_PRODUCTS_URL || "";

  if (!productsUrl) return;

  try {
    const headers = {
      "Content-Type": "application/json"
    };

    if (isConfigured(VIP_API_KEY)) {
      headers.Authorization = `Bearer ${VIP_API_KEY}`;
      headers["X-API-Key"] = VIP_API_KEY;
    }

    const response = await axios.get(productsUrl, {
      headers,
      timeout: 30000
    });

    const list = normalizeProductList(response.data);

    for (const item of list) {
      const key = productKey(item);
      const price = priceOf(item);

      if (key && price > 0) {
        prices[key] = {
          ...item,
          price,
          updatedAt: new Date().toISOString()
        };
      }
    }

    savePrices();

    console.log(
      `Harga VIP tersinkron: ${Object.keys(prices).length} produk`
    );
  } catch (error) {
    console.error(
      "SYNC PRICES:",
      error.response?.data || error.message
    );
  }
}

app.get("/api/products", async (req, res) => {
  try {
    if (!Object.keys(vipCatalog).length || req.query.refresh === "1") {
      await refreshVipCatalog(req.query.refresh === "1" ? "manual-products" : "products-first-load");
    }
    let catalogSettings = { disabled: [], customPrice: {}, order: [] };
    try { catalogSettings = JSON.parse(fs.readFileSync(CATALOG_SETTINGS_FILE, "utf8")); } catch {}
    const disabledSet = new Set((catalogSettings.disabled || []).map(String));

    const products = Object.values(vipCatalog)
      .map(normalizeVipCatalogItem)
      .filter(Boolean)
      .map(p => {
        const isDisabledByAdmin = disabledSet.has(p.code) || disabledSet.has(p.name);
        const isAvailable = String(p.status).toLowerCase() === "available" && !isDisabledByAdmin;
        const customPrice = catalogSettings.customPrice && catalogSettings.customPrice[p.code];
        if (customPrice) p.sellingPrice = Number(customPrice);
        return {
          ...p,
          isActive: isAvailable,
          isDisabledByAdmin,
          reason: !isAvailable ? (isDisabledByAdmin ? "Dinonaktifkan oleh admin" : "Tidak tersedia dari provider") : null
        };
      });

    // filter hanya available jika query ?onlyActive=1, tapi default kembalikan semua biar frontend bisa tampilkan nonaktif
    const onlyActive = req.query.onlyActive === "1";
    const filtered = onlyActive ? products.filter(x => x.isActive) : products;

    res.set("Cache-Control", "no-store");
    res.json({
      success: true,
      priceLevel: String(process.env.VIP_PRICE_LEVEL || "basic").toLowerCase(),
      lastSyncAt: vipCatalogMeta.lastSyncAt || null,
      count: filtered.length,
      totalCount: products.length,
      catalogSettings,
      products: filtered
    });
  } catch (error) {
    console.error("VIP PRODUCTS:", error.response?.data || error.message);
    res.status(502).json({ success: false, message: error.message || "Gagal mengambil produk VIP Reseller" });
  }
});

