async function processPendingVipOrders() {
  // Dicek per-order di refreshOrderStatus() apakah provider order itu (VIP
  // atau MeloStore) sudah dikonfigurasi, jadi di sini tidak berhenti total
  // hanya karena salah satu provider belum diisi.
  for (const order of Object.values(orders)) {
    if (
      order &&
      order.paymentStatus === "SUCCESS" &&
      order.topupStatus === "PROCESSING" &&
      order.vipTrxId
    ) {
      await refreshOrderStatus(order);
    }
  }
}

/* =========================================================
   START
========================================================= */

async function processPaymentReminders() {
  const now=Date.now(); let changed=false;
  for(const order of Object.values(orders)){
    if(!order || order.paymentStatus!=="PENDING" || order.status!=="WAITING_PAYMENT" || !order.email) continue;
    if(order.expiresAt && now > Number(order.expiresAt)) continue;
    const count=Number(order.paymentReminderCount||0), last=order.lastPaymentReminderAt?new Date(order.lastPaymentReminderAt).getTime():0;
    const age=now-new Date(order.createdAt||now).getTime();
    if(age < 10*60*1000 || count>=2 || (last && now-last<20*60*1000)) continue;
    await sendPaymentReminder(order); changed=true;
  }
  if(changed) saveOrders();
}
function releaseOrderReservation(order) {
  try {
    if (!order) return;
    if (Number(order.reservedStock||0) > 0) order.reservationReleased = Number(order.reservedStock||0);
    if (Number(order.reservedSlot||0) > 0) order.reservationSlotReleased = Number(order.reservedSlot||0);
    order.reservationReleasedAt = new Date().toISOString();
  } catch {}
}
function expireUnpaidOrders() {
  const now=Date.now(); let changed=false;
  for(const order of Object.values(orders)) {
    if(!order || order.paymentStatus!=="PENDING") continue;
    if(!order.expiresAt || now <= Number(order.expiresAt)) continue;
    if(["EXPIRED","SUCCESS","FAILED"].includes(String(order.status||""))) continue;
    order.paymentStatus="EXPIRED"; order.status="EXPIRED"; order.topupStatus="NOT_STARTED"; order.expiredAt=new Date().toISOString();
    releaseOrderReservation(order); order.updatedAt=order.expiredAt; changed=true;
  }
  if(changed) saveOrders();
  return changed;
}
function buildDevDashboard() {
  const all=Object.values(orders||{}); const now=Date.now(); const day=new Date(now+7*3600*1000).toISOString().slice(0,10); const month=day.slice(0,7);
  const summary={today:{orders:0,revenue:0,success:0,failed:0,pending:0},month:{orders:0,revenue:0,success:0,failed:0,pending:0},paymentMethods:{},fee:0,profit:0,topProducts:[]}; const products={};
  for(const o of all){ const d=String(o.createdAt||"").slice(0,10); const isToday=d===day, isMonth=d.startsWith(month); const success=o.topupStatus==="SUCCESS"&&o.paymentStatus==="SUCCESS"&&o.refundStatus!=="REFUNDED"; const failed=o.topupStatus==="FAILED"||o.status==="FAILED"||o.status==="TOPUP_FAILED"; const pending=!success&&!failed&&o.paymentStatus!=="EXPIRED"; const rev=Number(o.baseAmount||0); const fee=Number(o.serviceFeeAmount||0); if(isToday){summary.today.orders++;summary.today.revenue+=rev;if(success)summary.today.success++;else if(failed)summary.today.failed++;else if(pending)summary.today.pending++;} if(isMonth){summary.month.orders++;summary.month.revenue+=rev;if(success)summary.month.success++;else if(failed)summary.month.failed++;else if(pending)summary.month.pending++;} if(success){const c=orderCostInfo(o).cost;summary.profit+=rev-c;} summary.fee+=fee; const m=o.paymentMethod||"Unknown"; summary.paymentMethods[m]=(summary.paymentMethods[m]||0)+1; const prod=o.product||o.game||"Lainnya"; products[prod]=(products[prod]||0)+1; }
  summary.topProducts=Object.entries(products).sort((a,b)=>b[1]-a[1]).slice(0,10).map(([name,count])=>({name,count})); return summary;
}

function dailyBackupCheck(){
  const marker=path.join(BACKUP_DIR,".daily-marker"); const today=new Date().toISOString().slice(0,10); const last=fs.existsSync(marker)?fs.readFileSync(marker,"utf8").trim():"";
  if(last!==today){ const r=createBackup("daily"); if(r.success) fs.writeFileSync(marker,today); }
}

app.listen(PORT, async () => {
  console.log(`TOPUP STORE aktif di port ${PORT}`);

  try {
    if (isConfigured(SMTP_USER) && isConfigured(SMTP_PASS)) {
      await getMailer().verify();
      console.log("SMTP email: TERHUBUNG");
    } else {
      console.log("SMTP email: belum dikonfigurasi");
    }
  } catch (error) {
    console.log("SMTP email: GAGAL -", error.message);
  }

  syncPrices();
  refreshVipCatalog("startup");
  refreshMeloCatalog("startup");
  checkProviderHealth();
  setInterval(syncPrices, 10 * 60 * 1000);
  setInterval(() => refreshVipCatalog("interval"), 60 * 1000);
  setInterval(() => refreshMeloCatalog("interval"), 60 * 1000);
  setInterval(() => processPendingVipOrders().catch(err => console.error("ORDER POLLING:", err.message)), 30 * 1000);
  setInterval(() => checkProviderHealth().catch(e=>console.log("health check", e.message)), 60 * 1000);
  setInterval(() => recoverPendingOrders().catch(e=>console.log('recover', e.message)), 5 * 60 * 1000);
  // Rekonsiliasi tiap 6 jam + tiap pagi jam 6
  setInterval(() => reconcileIpaymu().catch(e=>console.log('reconcile', e.message)), 6 * 60 * 60 * 1000);
  setInterval(() => processPaymentReminders().catch(e=>console.log("payment reminder",e.message)), 5 * 60 * 1000);
  setInterval(() => expireUnpaidOrders(), 60 * 1000);
  expireUnpaidOrders();
  setInterval(dailyBackupCheck, 60 * 60 * 1000);
  dailyBackupCheck();
  // Jalankan reconcile pertama 2 menit setelah start
  setTimeout(() => reconcileIpaymu().catch(()=>{}), 2 * 60 * 1000);
});

